export const QUESTIONS_433A = [
  // ═══ BLOCK A: Common Occupational Skills (25) ═══
  { id:1,cat:"A",q:"What is required when working from heights?",opts:["Hard hat","Fall arrest equipment","Safety glasses","Steel-toed boots"],ans:1,exp:"Fall arrest equipment is mandatory for heights to prevent falls — the #1 cause of workplace fatalities in trades.",type:"recall"},
  { id:2,cat:"A",q:"Before performing maintenance on a machine, what must be done first?",opts:["Notify supervisor","Apply lockout/tagout procedures","Put on safety glasses","Read service manual"],ans:1,exp:"LOTO isolates all energy sources (electrical, pneumatic, hydraulic, mechanical, gravity) to prevent accidental startup. Legally required under OHSA.",type:"procedure"},
  { id:3,cat:"A",q:"What does WHMIS stand for?",opts:["Workplace Hazard Management and Inspection System","Workplace Hazardous Materials Information System","Worker Health and Material Inventory Standards","Workplace Hazard Monitoring and Inspection Services"],ans:1,exp:"WHMIS — Workplace Hazardous Materials Information System — is Canada's national hazard communication standard.",type:"recall"},
  { id:4,cat:"A",q:"A GHS pictogram showing a flame over a circle indicates what hazard?",opts:["Flammable","Oxidizer","Explosive","Compressed gas"],ans:1,exp:"Flame-over-circle = oxidizer. Simple flame = flammable. Exploding bomb = explosive. Gas cylinder = compressed gas.",type:"recall"},
  { id:5,cat:"A",q:"Which instrument measures bore inside diameter to 0.001\" accuracy?",opts:["Outside micrometer","Telescoping gauge and micrometer","Vernier caliper","Steel rule and divider"],ans:1,exp:"Telescoping gauge inserted into the bore, locked, then measured with an outside micrometer for 0.001\" precision.",type:"procedure"},
  { id:6,cat:"A",q:"What type of file is used for finishing soft metals like aluminum?",opts:["Double-cut bastard","Single-cut smooth file","Rasp-cut file","Double-cut second-cut"],ans:1,exp:"Single-cut smooth files produce a finer finish on soft metals and resist loading (clogging) better than double-cut.",type:"recall"},
  { id:7,cat:"A",q:"A dial indicator checking shaft runout reads 0.006\". What is the TIR?",opts:["0.003\"","0.006\"","0.012\"","0.009\""],ans:1,exp:"TIR = Total Indicator Reading = full sweep from low to high. If the indicator reads 0.006\", the TIR IS 0.006\".",type:"critical"},
  { id:8,cat:"A",q:"A torque wrench reads 50 ft-lbs. What is this in Newton-meters?",opts:["36.9 N·m","67.8 N·m","50 N·m","73.7 N·m"],ans:1,exp:"1 ft-lb = 1.3558 N·m → 50 × 1.3558 = 67.79 ≈ 67.8 N·m. Unit conversion is critical for metric/imperial specs.",type:"critical"},
  { id:9,cat:"A",q:"On a blueprint, what does a hidden line (dashed) represent?",opts:["Center of a feature","An edge not visible in current view","A cutting plane","A dimension extension"],ans:1,exp:"Hidden lines (short dashes) show edges that exist but aren't visible from the current viewing angle.",type:"recall"},
  { id:10,cat:"A",q:"A drawing calls for 3/8\"-16 UNC. What does '16' mean?",opts:["Bolt length in sixteenths","Threads per inch","Tensile strength grade","Head size in mm"],ans:1,exp:"In UNC thread designation: 3/8\" = major diameter, 16 = threads per inch (TPI).",type:"recall"},
  { id:11,cat:"A",q:"When lighting an oxy-acetylene torch, which gas is turned on first?",opts:["Oxygen","Acetylene","Either one","Both simultaneously"],ans:1,exp:"Acetylene always first on, oxygen added to adjust flame. Shutdown: close oxygen first, then acetylene.",type:"procedure"},
  { id:12,cat:"A",q:"What type of fit allows hand assembly with slight clearance?",opts:["Interference fit","Sliding fit (clearance fit)","Transition fit","Shrink fit"],ans:1,exp:"Sliding/clearance fit: shaft slightly smaller than hole. Interference fits require force; shrink fits use heat.",type:"recall"},
  { id:13,cat:"A",q:"A metric bolt marked 8.8 — what does the first '8' indicate?",opts:["Yield strength class","Ultimate tensile strength ~800 MPa","Thread pitch","Rockwell C hardness"],ans:1,exp:"Grade 8.8: first number × 100 = UTS (800 MPa). Second × first × 100 = yield (640 MPa).",type:"recall"},
  { id:14,cat:"A",q:"When pressing a bearing onto a shaft, force should be applied to:",opts:["Outer race","Inner race","Rolling elements","Cage"],ans:1,exp:"Force on inner race when mounting on shaft. Force on outer race when pressing into housing. Wrong application damages rolling elements.",type:"procedure"},
  { id:15,cat:"A",q:"What is the correct procedure for tapping a hole in mild steel?",opts:["Drill, ream, then tap","Drill tap-drill size, chamfer, tap with cutting fluid","Drill, countersink, then tap","Drill oversize, force tap"],ans:1,exp:"Drill correct tap-drill size → chamfer entrance → tap with cutting fluid for lubrication and chip clearing.",type:"procedure"},
  { id:16,cat:"A",q:"The most effective training approach when mentoring an apprentice is:",opts:["Let them figure it out independently","Demonstrate, explain, then supervised practice","Give written manuals only","Observe for months first"],ans:1,exp:"Show-tell-do method (demonstrate → explain → supervised practice) is most effective for skilled trades apprenticeships.",type:"recall"},
  { id:17,cat:"A",q:"A complete maintenance report should include:",opts:["Only parts replaced","Work done, parts used, time, and recommendations","Only time spent","Symptoms only"],ans:1,exp:"Document: work performed, parts consumed, labor time, root cause, and recommendations for prevention.",type:"recall"},
  { id:18,cat:"A",q:"When is it appropriate to deviate from manufacturer's procedures?",opts:["When you have more experience","Never without engineering approval and documentation","When supervisor says OK verbally","When old procedure worked before"],ans:1,exp:"Changes require proper engineering review, approval, and documentation. Unauthorized changes void warranties and create hazards.",type:"procedure"},
  { id:19,cat:"A",q:"A vernier micrometer reads: sleeve 0.275\", thimble 0.015\", vernier 0.0003\". Total?",opts:["0.2903\"","0.2900\"","0.2906\"","0.2953\""],ans:0,exp:"Add all readings: 0.275 + 0.015 + 0.0003 = 0.2903\". Always sum sleeve + thimble + vernier.",type:"critical"},
  { id:20,cat:"A",q:"A precision level shows 0.005\"/ft slope over 10 ft. Total rise?",opts:["0.005\"","0.050\"","0.500\"","0.025\""],ans:1,exp:"Rise = slope/ft × feet = 0.005 × 10 = 0.050\". Essential for leveling machine bases.",type:"critical"},
  { id:21,cat:"A",q:"What layout tool scribes circles and arcs on metal?",opts:["Prick punch","Divider or trammel","Center punch","Scriber"],ans:1,exp:"Dividers for small radii, trammels for large radii — both scribe accurate circles on metal workpieces.",type:"recall"},
  { id:22,cat:"A",q:"A dial bore gauge primarily measures:",opts:["Outside diameters","Internal bore diameters and taper","Shaft runout","Surface finish"],ans:1,exp:"Dial bore gauges measure bore IDs with high precision and detect taper, out-of-round, and bell-mouth conditions.",type:"recall"},
  { id:23,cat:"A",q:"Which tool checks flatness of a surface plate?",opts:["Feeler gauge alone","Precision straight edge with feeler gauges","Dial indicator","Height gauge"],ans:1,exp:"Place straight edge on surface, use feeler gauges to detect gaps — standard method for flatness verification.",type:"procedure"},
  { id:24,cat:"A",q:"Welding electrode E7018 — what does '8' mean?",opts:["High-cellulose potassium","Low-hydrogen iron powder coating","Rutile dioxide","High iron oxide"],ans:1,exp:"E7018: E=electrode, 70=70ksi tensile, 1=all positions, 8=low-hydrogen iron powder. Preferred for structural work.",type:"recall"},
  { id:25,cat:"A",q:"For oxy-fuel cutting 1\" mild steel, which flame type?",opts:["Carburizing","Neutral flame","Oxidizing","Reducing"],ans:1,exp:"Neutral flame (equal O₂ and acetylene) preheats to cherry red, then the cutting oxygen jet oxidizes and blows molten metal.",type:"procedure"},

  // ═══ BLOCK B: Rigging, Hoisting & Moving (17) ═══
  { id:26,cat:"B",q:"What is the sling stress formula?",opts:["(L ÷ H × W) ÷ Number of legs","(W × H) ÷ L","W ÷ Number of slings","W × angle factor"],ans:0,exp:"Sling stress = (Length ÷ Height × Weight) ÷ Legs. As angle from vertical increases, stress increases dramatically.",type:"critical"},
  { id:27,cat:"B",q:"10,000 lb load, 2-leg sling at 60° from horizontal. Load per leg?",opts:["5,000 lbs","5,774 lbs","7,071 lbs","10,000 lbs"],ans:1,exp:"At 60° from horizontal (30° from vertical): (10,000 ÷ 2) ÷ cos(30°) = 5000 ÷ 0.866 = 5,774 lbs.",type:"critical"},
  { id:28,cat:"B",q:"WLL of 1/2\" diameter 6×19 wire rope?",opts:["1 ton","2 tons","4 tons","8 tons"],ans:1,exp:"WLL = d² × 8 = (0.5)² × 8 = 2 tons. This formula is provided on the Red Seal exam.",type:"critical"},
  { id:29,cat:"B",q:"Wire rope clips required for 3/4\" diameter rope?",opts:["3","4","5","6"],ans:1,exp:"For ≤7/8\" rope: clips = 3 × diameter(in eighths fraction math) + 1. For 3/4\" = 4 clips. Formula on exam.",type:"critical"},
  { id:30,cat:"B",q:"Correct spacing for wire rope clips?",opts:["4 × rope diameter","6 × rope diameter","8 × rope diameter","3 × rope diameter"],ans:1,exp:"Clip spacing = 6 × rope diameter. For 1/2\" rope: 6 × 0.5 = 3\" between clips.",type:"recall"},
  { id:31,cat:"B",q:"What does a 'critical lift' plan require?",opts:["Verbal agreement","Written plan reviewed by competent person","Only crane cert","Supervisor verbal OK"],ans:1,exp:"Critical lifts: formal written plan with load weight, crane capacity at radius, rigging, ground conditions, weather — reviewed by competent person.",type:"procedure"},
  { id:32,cat:"B",q:"Weight of steel plate 4' × 8' × 1\" thick? (steel = 490 lbs/ft³)",opts:["1,307 lbs","1,044 lbs","980 lbs","1,568 lbs"],ans:0,exp:"Volume = 4 × 8 × (1/12) = 2.667 ft³ → 2.667 × 490 = 1,307 lbs. Convert 1\" to 1/12 ft.",type:"critical"},
  { id:33,cat:"B",q:"When should tag lines be used during a lift?",opts:["Only loads over 5 tons","Always — to control rotation and swing","Only in wind","Only when signal person requests"],ans:1,exp:"Tag lines control load rotation/swing and keep workers safely away from suspended loads. Required for every lift.",type:"recall"},
  { id:34,cat:"B",q:"Minimum recommended sling angle from horizontal?",opts:["30°","45°","60°","90°"],ans:2,exp:"60° minimum from horizontal. Below 60°, sling stress spikes and horizontal crushing forces become dangerous.",type:"recall"},
  { id:35,cat:"B",q:"As crane radius increases, what happens to capacity?",opts:["Increases","Decreases","Stays same","Doubles"],ans:1,exp:"Capacity decreases with increased radius due to greater tipping moment. Always check load chart at actual working radius.",type:"recall"},
  { id:36,cat:"B",q:"Hand signal for 'HOIST' (raise)?",opts:["Arm extended, thumb up","Small circular motion, finger pointing up","Both fists, thumbs up","Arm horizontal, palm down"],ans:1,exp:"HOIST = small horizontal circular motion with index finger pointing up. Universal crane signal.",type:"recall"},
  { id:37,cat:"B",q:"Synthetic sling has visible cuts through 10% of width. Action?",opts:["Reduce load 10%","Remove from service and destroy","Wrap with tape","Continue if under 25% damage"],ans:1,exp:"Any visible damage → immediately remove and destroy to prevent reuse. No acceptable damage threshold.",type:"procedure"},
  { id:38,cat:"B",q:"Which hitch reduces sling capacity the most?",opts:["Vertical hitch","Basket hitch","Choker hitch","Bridle hitch"],ans:2,exp:"Choker hitch reduces capacity to ~75-80% due to sharp bend and crushing force at the choke point.",type:"recall"},
  { id:39,cat:"B",q:"Using come-alongs horizontally — what must be verified?",opts:["Load is painted","Anchor capacity, pull direction, rated capacity","Only correct size","3+ workers present"],ans:1,exp:"Verify anchor point capacity, straight-line pull (no side loading), and come-along rated capacity for the task.",type:"procedure"},
  { id:40,cat:"B",q:"Proper wire rope sling storage?",opts:["Coiled on ground","Hung on rack, dry area, lubricated","Sealed plastic bag","Stacked pile"],ans:1,exp:"Hang vertically on rack in dry, ventilated area. Keep lubricated. Floor storage causes kinking and deterioration.",type:"procedure"},
  { id:41,cat:"B",q:"What must be checked on chain slings before each use?",opts:["Color coding only","Links for stretch, wear, gouges, cracks, twists","Master link only","Hooks only"],ans:1,exp:"Inspect ALL links for elongation (>5%), wear, gouges, cracks, twists. Check hooks and master links for damage.",type:"procedure"},
  { id:42,cat:"B",q:"A shackle screw pin's primary purpose?",opts:["Decorative finish","Securely close shackle body for load attachment","Wear indicator","Limit sling angle"],ans:1,exp:"Screw pin closes the shackle for secure sling/cable attachment. Must be fully seated and tightened.",type:"recall"},

  // ═══ BLOCK C: Mechanical Power Transmission (32) ═══
  { id:43,cat:"C",q:"Most common cause of electric motor failure?",opts:["Shaft misalignment","Bearing failure from improper lubrication","Voltage fluctuation","Manufacturing defect"],ans:1,exp:"Bearing failure is #1 — usually from improper lubrication (too much/little/wrong type), contamination, or misalignment.",type:"recall"},
  { id:44,cat:"C",q:"Diesel engine running rough with black smoke — likely cause?",opts:["Low coolant","Overfueling or restricted air intake","Low oil pressure","Faulty alternator"],ans:1,exp:"Black smoke = incomplete combustion from overfueling or restricted air. White = coolant intrusion. Blue = oil burning.",type:"critical"},
  { id:45,cat:"C",q:"Purpose of a flywheel on a prime mover?",opts:["Increase speed","Store rotational energy, smooth power pulses","Reduce startup vibration only","Connect to driven equipment"],ans:1,exp:"Flywheel stores kinetic energy between power strokes, smoothing pulsating torque for more constant speed output.",type:"recall"},
  { id:46,cat:"C",q:"Replacing an electric motor — which nameplate data must match?",opts:["Color and weight","HP, RPM, voltage, frame size, enclosure type","Only horsepower","Brand only"],ans:1,exp:"Match: HP, RPM, voltage, phase, frame size (mounting dims), enclosure (TEFC, ODP), and service factor.",type:"procedure"},
  { id:47,cat:"C",q:"Which prime mover converts fluid pressure to rotational energy?",opts:["Electric motor","Hydraulic motor","ICE engine","Air compressor"],ans:1,exp:"Hydraulic motor converts hydraulic pressure/flow into rotational mechanical energy.",type:"recall"},
  { id:48,cat:"C",q:"Purpose of pre-loading tapered roller bearings?",opts:["Increase friction","Eliminate internal clearance, ensure contact","Easier installation","Reduce load capacity"],ans:1,exp:"Pre-load eliminates clearance, ensures full roller contact, prevents skidding, improves rigidity and accuracy.",type:"recall"},
  { id:49,cat:"C",q:"Fretting corrosion at bearing seat — likely cause?",opts:["Excessive speed","Loose fit between inner race and shaft","Over-lubrication","Shaft too hard"],ans:1,exp:"Fretting (reddish-brown oxidation) = micro-movement from too-loose fit. Fix with proper interference fit.",type:"critical"},
  { id:50,cat:"C",q:"What seal type prevents oil leakage along a rotating shaft?",opts:["O-ring","Lip seal (oil seal)","Gasket","Mechanical face seal"],ans:1,exp:"Lip seals with spring-loaded lip contact the shaft surface. For higher pressure, mechanical face seals are used.",type:"recall"},
  { id:51,cat:"C",q:"When removing a bearing with a puller, grip which part?",opts:["Cage/retainer","Inner race","Outer race","Rolling elements"],ans:1,exp:"Pull from the inner race — that's where the interference fit is. Pulling outer race or cage damages the bearing.",type:"procedure"},
  { id:52,cat:"C",q:"Which bearing handles both radial and thrust loads?",opts:["Cylindrical roller","Angular contact bearing","Needle roller","Thrust bearing"],ans:1,exp:"Angular contact bearings have angled raceways for combined radial + axial loads. Tapered rollers also work.",type:"recall"},
  { id:53,cat:"C",q:"Shaft journal shows blue discoloration. Indicates?",opts:["Normal oxidation","Overheating from insufficient lubrication","Properly hardened","Chemical contamination"],ans:1,exp:"Blue = overheated (>500°F/260°C). Usually from lost lubrication. Metallurgy may be altered — shaft may need replacement.",type:"critical"},
  { id:54,cat:"C",q:"Which coupling compensates for angular, parallel, and axial misalignment?",opts:["Rigid coupling","Jaw (spider) coupling","Disc coupling","Gear coupling"],ans:1,exp:"Jaw couplings with elastomeric spider handle all three misalignment types plus vibration dampening.",type:"recall"},
  { id:55,cat:"C",q:"Clutch disc contaminated with oil — what happens?",opts:["Friction increases","Clutch slips, reduced torque transmission","No effect","Faster engagement"],ans:1,exp:"Oil reduces friction coefficient → slippage → can't transmit full torque. Replace disc, fix oil leak source.",type:"critical"},
  { id:56,cat:"C",q:"Disc brake not releasing fully — most likely cause?",opts:["Pads too thick","Return spring broken or weak","Disc too clean","Caliper too tight"],ans:1,exp:"Weak/broken return spring → pads drag on disc → heat buildup, premature wear, energy loss.",type:"critical"},
  { id:57,cat:"C",q:"Purpose of a grid coupling?",opts:["Connect identical shafts only","Transmit torque, absorb shock, accommodate misalignment","Lock shafts permanently","Increase speed"],ans:1,exp:"Grid couplings use a tapered metallic grid spring that flexes to absorb shock and accommodate slight misalignment.",type:"recall"},
  { id:58,cat:"C",q:"How is roller chain slack measured?",opts:["Counting loose links","Measuring deflection at mid-span","Pulling chain tight","Weighing the chain"],ans:1,exp:"Measure sag at mid-span between sprockets. Proper slack = 2-4% of center distance for horizontal runs.",type:"procedure"},
  { id:59,cat:"C",q:"V-belt drive slipping — first action?",opts:["Replace all belts","Check and adjust belt tension","Increase motor speed","Add belt dressing"],ans:1,exp:"Check tension first — most common cause. Never use belt dressing (damages belts). If tension OK, check sheave/belt wear.",type:"procedure"},
  { id:60,cat:"C",q:"Multi-belt V-belt drive — when replacing belts:",opts:["Replace only worn ones","Replace ALL as a matched set","Mix old and new","Use any that fit"],ans:1,exp:"Always replace ALL belts. Mixing causes uneven loading — worn belts ride lower in groove → rapid new belt failure.",type:"procedure"},
  { id:61,cat:"C",q:"What causes chain 'stretch'?",opts:["Steel links elongate","Wear on pins and bushings","Temperature expansion","Improper lubrication only"],ans:1,exp:"'Stretch' = accumulated wear on pins/bushings at each joint, not steel elongation. Replace at 3% over nominal.",type:"recall"},
  { id:62,cat:"C",q:"What gear type transmits motion between perpendicular shafts?",opts:["Spur gears","Bevel gears","Helical gears","Herringbone gears"],ans:1,exp:"Bevel gears transmit power between intersecting shafts (typically 90°). Worm gears also work at 90° but don't intersect.",type:"recall"},
  { id:63,cat:"C",q:"Gear reducer: 1750 RPM input, 5:1 ratio. Output speed?",opts:["8750 RPM","350 RPM","1750 RPM","175 RPM"],ans:1,exp:"Output = Input ÷ Ratio = 1750 ÷ 5 = 350 RPM. Speed decreases, torque increases.",type:"critical"},
  { id:64,cat:"C",q:"Pitting pattern on gear teeth indicates?",opts:["Proper break-in","Surface fatigue from overloading","Normal wear","Teeth too hard"],ans:1,exp:"Pitting = surface fatigue from repeated high contact stresses. Caused by overloading, misalignment, or poor lubrication.",type:"critical"},
  { id:65,cat:"C",q:"After replacing gears, what must be checked?",opts:["New gear dimensions only","Backlash, tooth contact pattern, lubrication","Oil level only","Gear color match"],ans:1,exp:"Check backlash with feeler gauge/dial indicator, verify contact pattern with marking compound, ensure proper lube.",type:"procedure"},
  { id:66,cat:"C",q:"Gear mesh frequency formula?",opts:["RPM × number of teeth","RPM ÷ number of teeth","Teeth ÷ RPM","RPM² × teeth"],ans:0,exp:"Gear mesh frequency = RPM × teeth. Used in vibration analysis to identify gear problems. On the Red Seal exam.",type:"recall"},
  { id:67,cat:"C",q:"Most accurate shaft alignment method?",opts:["Straight edge and feeler gauge","Reverse dial indicator","Laser alignment","Visual alignment"],ans:2,exp:"Laser = most accurate, fastest, most repeatable. Reverse dial indicator is also very accurate. Straight edge for rough only.",type:"recall"},
  { id:68,cat:"C",q:"Two types of shaft misalignment?",opts:["Vertical and horizontal","Angular and offset (parallel)","Axial and radial","Linear and rotational"],ans:1,exp:"Angular (shafts at an angle) and offset/parallel (shafts parallel but not collinear). Most real cases combine both.",type:"recall"},
  { id:69,cat:"C",q:"Dial indicator: 0.010\" at 12 o'clock, 0.002\" at 6 o'clock. Offset?",opts:["0.010\"","0.004\"","0.012\"","0.008\""],ans:1,exp:"Offset = (Top – Bottom) ÷ 2 = (0.010 – 0.002) ÷ 2 = 0.004\". Divide TIR by 2 for actual centerline offset.",type:"critical"},
  { id:70,cat:"C",q:"Why account for thermal growth during alignment?",opts:["Makes bolts tighter","Machines change position at operating temperature","Only affects foundation","Negligible in industry"],ans:1,exp:"Shafts, housings, supports expand with heat, shifting centerlines. Cold alignment must compensate for expected thermal growth.",type:"recall"},
  { id:71,cat:"C",q:"What corrects soft foot during alignment?",opts:["Hammer","Shims under machine feet","Level","Torque wrench only"],ans:1,exp:"Precision shims under affected foot ensure all feet bear evenly. Soft foot distorts the frame, preventing accurate alignment.",type:"procedure"},
  { id:72,cat:"C",q:"Alignment shim calculation uses which variables?",opts:["Shaft diameter only","Gap, distance between supports, distance to correction","Dial reading only","Coupling diameter and torque"],ans:1,exp:"Shims = G × (A/B) where G = gap/offset, A = distance to correction, B = distance between measurement points.",type:"critical"},
  { id:73,cat:"C",q:"A fluid coupling showing excess heat and reduced efficiency needs:",opts:["Paint touch-up","Check fluid level, type, and internal wear","Speed increase","Nothing, this is normal"],ans:1,exp:"Check fluid level, verify correct fluid type, inspect for internal component wear. Normal operation = smooth, minimal heat.",type:"critical"},
  { id:74,cat:"C",q:"Timing belt alignment requires:",opts:["Angular only","Both parallel and angular alignment","No alignment needed","Axial only"],ans:1,exp:"Both parallel and angular alignment are required. Misalignment causes uneven wear, tracking issues, premature failure.",type:"procedure"},

  // ═══ BLOCK D: Material Handling / Process Systems (24) ═══
  { id:75,cat:"D",q:"Before entering a robotic work cell for maintenance?",opts:["Slow robot to min speed","Full lockout/tagout, isolate all energy","Unplug teach pendant only","Inform operator"],ans:1,exp:"Full LOTO of all energy sources. Robots can move unexpectedly if not completely de-energized.",type:"procedure"},
  { id:76,cat:"D",q:"Centrifugal fan vibrating excessively — most likely cause?",opts:["Motor too powerful","Impeller imbalance from material buildup","Ductwork too long","Inlet damper open"],ans:1,exp:"Material buildup on impeller blades causes imbalance and vibration. Regular cleaning/balancing is essential PM.",type:"critical"},
  { id:77,cat:"D",q:"What determines airflow direction in a centrifugal fan?",opts:["Motor speed","Scroll housing design","Blade thickness","Shaft diameter"],ans:1,exp:"The scroll (volute) housing: air enters axially, is accelerated by impeller, discharged tangentially from scroll outlet.",type:"recall"},
  { id:78,cat:"D",q:"Replacing fan bearings — what must be checked?",opts:["Bearing size only","Fit, shaft condition, housing bore, alignment","Lubrication type only","Motor amps only"],ans:1,exp:"Check: bearing-to-shaft fit, shaft condition (no scoring), housing bore, seal condition, post-install alignment.",type:"procedure"},
  { id:79,cat:"D",q:"Axial fans are used when:",opts:["High pressure needed","High volume at low pressure needed","Air must be filtered","Hot gases must move"],ans:1,exp:"Axial fans = high volume, low pressure (ventilation/cooling). Centrifugal fans develop higher pressures for duct systems.",type:"recall"},
  { id:80,cat:"D",q:"Centrifugal pump cavitating — most likely cause?",opts:["Discharge pressure too low","Insufficient NPSHa (suction restriction)","Impeller too large","Motor running backwards"],ans:1,exp:"Cavitation: NPSHa < NPSHr. Causes: clogged suction, high suction lift, high fluid temp, restricted suction piping.",type:"critical"},
  { id:81,cat:"D",q:"Which pump type uses an impeller?",opts:["Gear pump","Centrifugal pump","Diaphragm pump","Piston pump"],ans:1,exp:"Centrifugal pumps use rotating impeller → velocity → volute converts to pressure. Others are positive displacement.",type:"recall"},
  { id:82,cat:"D",q:"How tight should pump packing be?",opts:["As tight as possible","Allow slight drip for cooling/lubrication","Hand tight only","No adjustment needed"],ans:1,exp:"Must drip slightly (few drops/min) for cooling and lubrication. Over-tight = burned packing, scored sleeve.",type:"procedure"},
  { id:83,cat:"D",q:"Positive displacement pumps deliver:",opts:["Variable flow","Constant flow per revolution","Constant pressure","Variable pressure"],ans:1,exp:"PD pumps deliver fixed volume per revolution regardless of discharge pressure. That's why they need pressure relief protection.",type:"recall"},
  { id:84,cat:"D",q:"Most common cause of mechanical seal failure?",opts:["Wrong material","Dry running (no lubrication between faces)","Pump too large","Bolt torque too high"],ans:1,exp:"Dry running is #1 killer. The thin fluid film between seal faces provides lubrication + cooling. Even brief dry running destroys faces.",type:"critical"},
  { id:85,cat:"D",q:"Excessive discharge temp in reciprocating compressor — causes?",opts:["Oversized motor","Worn rings, broken valves, insufficient cooling","Inlet filter too clean","Tank too large"],ans:1,exp:"Worn piston rings (recirculation), broken valves, fouled cooler, low oil. Can cause oil ignition from carbon buildup.",type:"critical"},
  { id:86,cat:"D",q:"Purpose of aftercooler on compressed air system?",opts:["Increase pressure","Cool air and remove moisture","Filter air","Regulate flow"],ans:1,exp:"Reduces compressed air temp → water condenses out → separator removes liquid. Protects downstream equipment from moisture.",type:"recall"},
  { id:87,cat:"D",q:"Screw compressor oil separator — excessive carryover. Check?",opts:["Motor bearings","Separator element condition and oil level","Inlet filter only","Discharge piping"],ans:1,exp:"Check: element (clogged/damaged), oil level, minimum pressure valve, oil return line for blockage.",type:"procedure"},
  { id:88,cat:"D",q:"How often should compressor safety valves be tested?",opts:["Once per year","Per manufacturer and jurisdictional regulations","Only when faulty","Every 5 years"],ans:1,exp:"Test per manufacturer AND local jurisdictional regulations (often annually or scheduled shutdowns). Some require certified testing.",type:"procedure"},
  { id:89,cat:"D",q:"Two-stage reciprocating compressor — purpose of intercooler?",opts:["Increase HP","Cool air between stages, improve efficiency","Filter contaminants","Reduce noise"],ans:1,exp:"Intercooler cools air between stages. Cooler = denser = less work to compress further. Improves efficiency, reduces discharge temp.",type:"recall"},
  { id:90,cat:"D",q:"Pipe schedule number indicates:",opts:["Pipe length","Wall thickness","Outside diameter","Thread count"],ans:1,exp:"Schedule (40, 80, etc.) = wall thickness for given nominal size. Higher schedule = thicker = higher pressure rating.",type:"recall"},
  { id:91,cat:"D",q:"Purpose of expansion joint in piping?",opts:["Filter contaminants","Absorb thermal expansion/contraction","Increase pressure","Change flow direction"],ans:1,exp:"Absorbs thermal growth, vibration, movement. Without them, thermal forces damage supports, flanges, equipment.",type:"recall"},
  { id:92,cat:"D",q:"Pressure vessel pitting corrosion — safety determination based on:",opts:["Visual only","Remaining wall thickness vs minimum design requirement","Vessel age","Corrosion color"],ans:1,exp:"Remaining wall must meet ASME minimum. UT thickness testing measures remaining wall. Below minimum → repair/retire.",type:"critical"},
  { id:93,cat:"D",q:"Conveyor belt tracking to one side — likely cause?",opts:["Belt too long","Uneven tension or misaligned idlers","Load too heavy","Motor too fast"],ans:1,exp:"Mistracking: unequal tension, misaligned idlers, worn crowned pulleys, uneven loading, or frame distortion.",type:"critical"},
  { id:94,cat:"D",q:"Purpose of a belt scraper (cleaner) on conveyor?",opts:["Increase speed","Remove carryback from return side","Increase friction","Align the belt"],ans:1,exp:"Removes residual material (carryback) to prevent buildup on return idlers, mistracking, and cleanup issues.",type:"recall"},
  { id:95,cat:"D",q:"Screw conveyor vibrating with grinding noise — inspect:",opts:["Motor nameplate","Flights, trough wear, hanger bearings","Drive belt only","Discharge opening only"],ans:1,exp:"Check: worn flights contacting trough, worn liner, seized hanger bearings, bent screw sections, foreign objects.",type:"procedure"},
  { id:96,cat:"D",q:"Best conveyor for moving bulk materials vertically?",opts:["Belt conveyor","Bucket elevator","Roller conveyor","Chain conveyor"],ans:1,exp:"Bucket elevators scoop at boot, carry up, discharge at head by centrifugal force. Purpose-built for vertical bulk handling.",type:"recall"},
  { id:97,cat:"D",q:"Conveyor belt tensioning — adjustment made at:",opts:["Head pulley","Tail pulley or take-up device","Belt midpoint","Nearest idler"],ans:1,exp:"Tension at tail pulley (screw take-up) or gravity take-up. Allows tension and tracking adjustment. Head pulleys are fixed.",type:"procedure"},
  { id:98,cat:"D",q:"Installing flanged pipe gasket — use as lubricant:",opts:["Motor oil","Compatible anti-seize compound","WD-40","Silicone spray"],ans:1,exp:"Use anti-seize/gasket compound compatible with process fluid, temperature, and pressure. Wrong lube attacks gasket or contaminates process.",type:"procedure"},

  // ═══ BLOCK E: Fluid Power Systems (21) ═══
  { id:99,cat:"E",q:"Hydraulic force formula?",opts:["Force = Flow × Speed","Force = Pressure × Area","Force = Volume ÷ Time","Force = Pressure ÷ Area"],ans:1,exp:"F = P × A. Fundamental hydraulic formula. Area = piston area (π × r²). On the Red Seal exam.",type:"recall"},
  { id:100,cat:"E",q:"Hydraulic system running hot — check first:",opts:["Fluid color","Oil level, cooler, relief valve, internal leakage","Pump speed only","Motor only"],ans:1,exp:"Causes: low oil, clogged cooler, relief set too low, internal leakage (worn pump/cylinders/valves), contaminated/wrong oil.",type:"critical"},
  { id:101,cat:"E",q:"Purpose of hydraulic accumulator?",opts:["Filter oil","Store pressurized fluid for peaks, absorb shock","Increase pump speed","Cool oil"],ans:1,exp:"Stores energy for peak demands, absorbs shock, maintains pressure, compensates for leakage.",type:"recall"},
  { id:102,cat:"E",q:"Hydraulic cylinder drifting under load — cause?",opts:["Pump worn","Internal seal leakage past piston","Oil too cold","Reservoir too large"],ans:1,exp:"Internal leakage past piston seals lets oil bypass. External rod seal leaks cause fluid loss, not drift.",type:"critical"},
  { id:103,cat:"E",q:"Flow control valve regulates:",opts:["System pressure","Actuator speed","Fluid temperature","Pump RPM"],ans:1,exp:"Flow control = flow rate to actuators = speed. Relief valves control pressure. Flow = speed; Pressure = force.",type:"recall"},
  { id:104,cat:"E",q:"Hydraulic schematic: square with diagonal arrow =",opts:["Fixed displacement pump","Variable displacement pump/motor","Check valve","Filter"],ans:1,exp:"Diagonal arrow through pump/motor symbol = variable displacement. Without arrow = fixed displacement.",type:"recall"},
  { id:105,cat:"E",q:"Which valve controls direction of fluid to actuators?",opts:["Relief valve","Directional control valve","Flow control","Sequence valve"],ans:1,exp:"DCVs direct flow to/from actuators — determining cylinder extend/retract or motor rotation direction.",type:"recall"},
  { id:106,cat:"E",q:"Noisy pump + foamy reservoir oil — cause?",opts:["Oil too thick","Air entering suction line (aeration)","Pump too slow","Filter too restrictive"],ans:1,exp:"Foamy oil + noise = air intrusion. Causes: low oil, suction leak, damaged shaft seal, return line above oil level. Destroys pump rapidly.",type:"critical"},
  { id:107,cat:"E",q:"Piston area of 4\" bore hydraulic cylinder?",opts:["12.57 sq.in.","16 sq.in.","25.13 sq.in.","8 sq.in."],ans:0,exp:"A = π × r² = 3.1416 × (2)² = 12.57 sq.in. Bore = 4\" diameter, radius = 2\".",type:"critical"},
  { id:108,cat:"E",q:"Why never pressurize hydraulic system with compressed air?",opts:["Air too clean","Explosive failure — air stores much more energy","Air reduces pressure","Air is cheaper"],ans:1,exp:"Compressed air is highly compressible and stores enormous energy. Container failure = explosive release. Hydraulic fluid is nearly incompressible.",type:"recall"},
  { id:109,cat:"E",q:"When changing hydraulic filters — prevent contamination by:",opts:["Work fast","Clean area, pre-fill new filter, minimize open time","Wipe with rag","Only change when hot"],ans:1,exp:"Clean housing, pre-fill filter with clean fluid, minimize open time, use lint-free materials. Contamination = #1 system killer.",type:"procedure"},
  { id:110,cat:"E",q:"Most common cause of hydraulic system failure?",opts:["Pump defects","Fluid contamination (dirt, water, air)","Electrical issues","Cylinder rod damage"],ans:1,exp:"70-80% of failures from contamination. Proper filtration, clean fill procedures, and oil analysis are essential.",type:"recall"},
  { id:111,cat:"E",q:"Standard operating pressure for industrial pneumatic systems?",opts:["200 PSI","80-100 PSI (550-690 kPa)","30-40 PSI","150-175 PSI"],ans:1,exp:"Most industrial pneumatics: 80-100 PSI. Higher pressures increase energy costs without proportional benefit.",type:"recall"},
  { id:112,cat:"E",q:"What is an FRL unit?",opts:["Flow Rate Limiter","Filter, Regulator, Lubricator","Frequency Response Leveler","Fluid Return Line"],ans:1,exp:"FRL conditions compressed air: filter contaminants/moisture, regulate pressure, add oil mist for tool lubrication.",type:"recall"},
  { id:113,cat:"E",q:"Pneumatic cylinder moving slowly — check:",opts:["Bore size","Flow control, supply pressure, exhaust restrictions","Paint condition","Rod thread size"],ans:1,exp:"Check flow controls, supply pressure, exhaust restrictions, internal seal wear, undersized supply lines.",type:"procedure"},
  { id:114,cat:"E",q:"Danger of non-rated components in compressed air systems?",opts:["Reduced air quality","Catastrophic burst failure under pressure","Increased noise only","Slight efficiency loss"],ans:1,exp:"Non-rated components can burst catastrophically. All pneumatic components must be rated for system max pressure.",type:"recall"},
  { id:115,cat:"E",q:"Vacuum system losing suction — inspect:",opts:["Motor speed only","All connections for leaks, filter, pump wear","Reservoir only","Gauge color"],ans:1,exp:"Check: fittings/hoses/gaskets for leaks, filter/strainer blockage, vacuum pump wear (vanes, seals), check valve function.",type:"procedure"},
  { id:116,cat:"E",q:"Quick exhaust valve function?",opts:["Increases supply pressure","Fast exhaust at actuator for higher speed","Filters air","Regulates pressure"],ans:1,exp:"Mounts on cylinder port, vents exhaust locally instead of through control valve — dramatically increases retraction speed.",type:"recall"},
  { id:117,cat:"E",q:"Why is water removal critical in pneumatics?",opts:["Increases pressure","Causes corrosion, washes lubrication, freezes","No effect","Only affects reservoir"],ans:1,exp:"Water: corrodes internals, washes away lube films, freezes in exhaust ports (valve failure), reduces equipment efficiency.",type:"recall"},
  { id:118,cat:"E",q:"Pneumatic valve actuated by electrical signal?",opts:["Manual valve","Solenoid valve","Pilot-operated check","Needle valve"],ans:1,exp:"Solenoid valves use electromagnetic coil to shift spool, directing air flow. Enables PLC/automated control.",type:"recall"},
  { id:119,cat:"E",q:"Hissing from a pneumatic cylinder indicates:",opts:["Normal operation","Air leak from seals, fittings, or connections","Excessive pressure","Proper lubrication"],ans:1,exp:"Hissing = air leak. Check piston/rod seals, fittings, connections. Use soapy water on external joints to locate.",type:"critical"},

  // ═══ BLOCK F: Preventive & Predictive Maintenance (16) ═══
  { id:120,cat:"F",q:"Primary goal of preventive maintenance?",opts:["Fix after breakdown","Prevent unexpected breakdowns, extend equipment life","Reduce staff","Track warranties"],ans:1,exp:"PM prevents unexpected failures through scheduled inspections, lubrication, adjustments, and component replacement.",type:"recall"},
  { id:121,cat:"F",q:"Vibration at 1× RPM with high amplitude indicates:",opts:["Bearing defect","Imbalance","Misalignment","Looseness"],ans:1,exp:"Dominant 1× RPM = mass imbalance. Misalignment shows 2× RPM. Bearings show at specific bearing frequencies.",type:"critical"},
  { id:122,cat:"F",q:"Infrared thermography in electrical systems detects:",opts:["Voltage levels","Hot spots from loose connections, overloads, failing parts","Wire color","Current direction"],ans:1,exp:"Detects abnormal heat from loose connections (high resistance), overloaded conductors, failing breakers — before failure or fire.",type:"recall"},
  { id:123,cat:"F",q:"Oil analysis reveals:",opts:["Oil color only","Wear metals, contamination, oil degradation","Viscosity only","Temperature only"],ans:1,exp:"Identifies: wear metals (Fe, Cu, Pb = component wear), contaminants (dirt, water), oil condition (viscosity, oxidation, additives).",type:"recall"},
  { id:124,cat:"F",q:"Vibration spike at BPFO frequency — what is it?",opts:["Ball Point Frequency Oscillation","Ball Pass Frequency Outer Race — outer race defect","Bearing Peak Frequency Output","Basic Pump Frequency"],ans:1,exp:"BPFO = Ball Pass Frequency Outer race. Spike = defect (spall, crack, pit) on outer bearing race. BPFI = inner race.",type:"critical"},
  { id:125,cat:"F",q:"Over-greasing a bearing causes:",opts:["Better protection","Excessive heat, premature failure from churning","No negative effect","Improved speed"],ans:1,exp:"Elements churn excess grease → heat → friction → grease breakdown → blown seals. Follow 1/3 fill rule.",type:"recall"},
  { id:126,cat:"F",q:"Ultrasonic testing in predictive maintenance detects:",opts:["Temperature","Early bearing wear, leaks, electrical discharge","Shaft speed","Alignment"],ans:1,exp:"Detects: early bearing wear (before vibration can), air/gas/vacuum leaks, steam trap issues, electrical arcing/corona.",type:"recall"},
  { id:127,cat:"F",q:"A CMMS is used for:",opts:["Tracking parts only","PM scheduling, work orders, inventory, analysis","Sending emails only","Recording downtime only"],ans:1,exp:"CMMS manages: PM scheduling, work orders, spare parts, equipment history, labor tracking, maintenance cost analysis.",type:"recall"},
  { id:128,cat:"F",q:"Correct procedure for oil analysis sampling:",opts:["Dip cup into reservoir","Clean sampling port, system at operating temp, circulated","Take from drain plug","Sample when cold/settled"],ans:1,exp:"Sample from dedicated port at operating temp with oil circulated. Use clean bottles. Avoid drains (settled contaminants).",type:"procedure"},
  { id:129,cat:"F",q:"Vibration pattern indicating mechanical looseness:",opts:["Single 1× peak","Multiple harmonics (1×, 2×, 3×, 4×...)","Random broadband only","Single high-frequency peak"],ans:1,exp:"Looseness generates multiple harmonics and sub-harmonics. Creates 'picket fence' appearance in spectrum.",type:"critical"},
  { id:130,cat:"F",q:"Thermal expansion formula (on Red Seal exam):",opts:["Temp × Mass","ΔT × Length × Coefficient of expansion","Pressure × Volume","Heat × Density"],ans:1,exp:"Expansion = ΔT × L × α. Each material has its own coefficient. Critical for piping, shafts, machine bases.",type:"recall"},
  { id:131,cat:"F",q:"During commissioning, verify before startup:",opts:["Power connected only","Alignment, lubrication, rotation, safety devices, connections","Paint finish only","Nameplate only"],ans:1,exp:"Checklist: alignment, fluids filled, rotation direction (bump test), guards, safety devices, connections tight, follow manufacturer procedure.",type:"procedure"},
  { id:132,cat:"F",q:"Decommissioning — hazardous fluids must be:",opts:["Drained on ground","Collected, labeled, disposed per environmental regs","Left in machine","Poured down drain"],ans:1,exp:"All hazardous fluids properly collected, labeled, and disposed per provincial/federal environmental regulations. Improper disposal is illegal.",type:"procedure"},
  { id:133,cat:"F",q:"Newly installed pump vibrates excessively — check first:",opts:["Model number","Alignment, foundation bolts, piping strain, rotation","Flow rate only","Paint"],ans:1,exp:"First: shaft alignment (most common cause), foundation bolts, piping strain (forces on flanges), rotation direction, priming.",type:"procedure"},
  { id:134,cat:"F",q:"Documentation to update after commissioning:",opts:["Nothing","Equipment records, PM schedules, parts lists, as-built drawings","Purchase order only","Warranty card only"],ans:1,exp:"Update: equipment register, PM schedules in CMMS, spare parts, as-built drawings, alignment records, baseline readings.",type:"procedure"},
  { id:135,cat:"F",q:"'Bump test' during commissioning verifies:",opts:["Load capacity","Correct rotation direction of motors/pumps","Structural integrity","Paint adhesion"],ans:1,exp:"Briefly energizes motor to check rotation before full speed. Wrong rotation destroys pumps, fans, compressors instantly.",type:"procedure"},

  // ═══ EXPANSION QUESTIONS (136+) ═══
  { id:136,cat:"B",q:"What is the standard safety factor used for general rigging hardware?",opts:["2:1","5:1","10:1","20:1"],ans:1,exp:"General rigging hardware (shackles, hooks, slings) is designed to a 5:1 safety factor between rated capacity and minimum breaking strength.",type:"recall"},
  { id:137,cat:"B",q:"On a wire rope clip (U-bolt) installation, the U-bolt saddle must be placed on:",opts:["The dead (short) end","The live (standing) end","Either end, it doesn't matter","The center of the eye"],ans:1,exp:"\"Never saddle a dead horse\" — the saddle always bears on the live/standing part, with the U-bolt clamping the dead end.",type:"procedure"},
  { id:138,cat:"B",q:"A tag line attached to a suspended load is used to:",opts:["Increase the lifting capacity","Control rotation and swing of the load","Measure the load's weight","Replace the primary sling"],ans:1,exp:"A tag line is a handline used by ground crew to steady a load and prevent it from swinging or spinning during a lift.",type:"recall"},
  { id:139,cat:"B",q:"What happens to sling tension as the angle between a sling leg and the horizontal decreases (the sling becomes more horizontal)?",opts:["Tension decreases","Tension stays the same","Tension increases sharply","Tension becomes zero"],ans:2,exp:"As sling angle from horizontal decreases, tension in each leg increases dramatically — below 30° the load on each leg can exceed the load itself.",type:"critical"},
  { id:140,cat:"B",q:"A shackle pin should be:",opts:["Loose enough to spin freely","Hand-tight and fully seated, moused if a screw pin","Left finger-loose for easy removal","Replaced with a bolt for extra strength"],ans:1,exp:"Screw pin shackles must have the pin fully seated hand-tight, and moused (wired) if there's any risk of it backing out under vibration.",type:"procedure"},
  { id:141,cat:"B",q:"What is the primary purpose of a spreader bar in a rigging setup?",opts:["To increase total lifting capacity","To reduce severe sling angles on long loads","To replace the main hoist line","To act as a backup sling"],ans:1,exp:"A spreader bar keeps slings closer to vertical on long loads, avoiding excessive sling angle and the resulting overload.",type:"recall"},
  { id:142,cat:"B",q:"A wire rope sling with visible broken wires must be removed from service when:",opts:["Any broken wires are found on the outer strands","10 randomly distributed broken wires are found in one rope lay","It has been in service over 5 years regardless of condition","Only when the whole strand fails"],ans:1,exp:"Standard rejection criteria include 10 randomly distributed broken wires in one rope lay (or 5 in one strand), among other defects.",type:"recall"},
  { id:143,cat:"B",q:"When a hoist hook's throat opening has increased beyond the manufacturer's allowable deformation, the hook must be:",opts:["Bent back into shape with a torch","Removed from service immediately","Used only for lighter loads","Reinforced with a weld"],ans:1,exp:"A deformed throat opening indicates the hook has been overloaded and its integrity is compromised — it must be taken out of service.",type:"critical"},
  { id:144,cat:"B",q:"What is a choker hitch primarily used for?",opts:["Maximizing rated sling capacity","Gripping and controlling loose or bundled material","Lifting only rigid, single-piece loads","Eliminating the need for a hook"],ans:1,exp:"A choker hitch cinches around the load as tension is applied, useful for controlling bundles or materials without hard lift points.",type:"recall"},
  { id:145,cat:"B",q:"Before a mobile crane lift, checking the load chart requires knowing:",opts:["Only the load weight","Load weight, radius, boom length/angle, and configuration","Only the crane's make and model","Only the operator's certification level"],ans:1,exp:"Crane capacity varies with radius, boom length/angle, and configuration (outriggers, counterweight) — all must match the load chart used.",type:"critical"},
  { id:146,cat:"B",q:"A snatch block differs from a standard block because it:",opts:["Has no sheave","Opens on the side to accept a rope without threading the end","Can only be used for horizontal pulls","Has twice the sheave diameter"],ans:1,exp:"A snatch block has a hinged side plate letting you lay the rope in without feeding the end through — its defining feature.",type:"recall"},
  { id:147,cat:"B",q:"Reeving additional parts of line through a block and tackle system:",opts:["Increases speed of the load","Provides mechanical advantage at the cost of speed","Has no effect on force or speed","Is only done for aesthetic reasons"],ans:1,exp:"More reeved parts of line multiply the mechanical advantage (force) but proportionally reduce hook travel speed for the same input.",type:"recall"},
  { id:148,cat:"B",q:"The rated capacity of a basket hitch compared to a straight (vertical) sling hitch of the same sling is:",opts:["Exactly the same","Approximately double, if legs are vertical","Approximately half","Always zero — baskets aren't rated"],ans:1,exp:"A true vertical basket hitch shares the load across two sling legs, roughly doubling the rated capacity of a single vertical hitch — reduced as leg angle decreases from vertical.",type:"critical"},
  { id:149,cat:"B",q:"Fall protection is generally required to be used:",opts:["Only above 20 feet","Whenever there is a realistic possibility of a fall causing injury","Only when a supervisor is present","Only on scaffolding"],ans:1,exp:"General duty requires fall protection wherever a fall hazard with injury potential exists, not just above an arbitrary fixed height.",type:"recall"},
  { id:150,cat:"B",q:"A come-along (ratchet lever hoist) is limited compared to a wire-rope-grip puller because:",opts:["It cannot pull horizontally","Its pulling distance is limited to the length of chain/cable on its drum","It has no mechanical advantage","It can only lift, never pull"],ans:1,exp:"A come-along's travel is limited by the chain/cable length stored on it, unlike a Tirfor-style puller that feeds continuous wire rope through the machine.",type:"recall"},
  { id:151,cat:"B",q:"When rigging a load with an unknown weight, the first step should be to:",opts:["Guess based on similar past lifts","Calculate or look up the weight using material, volume, and density","Attach the largest available sling and proceed","Ask a coworker for a quick estimate"],ans:1,exp:"Safe rigging requires a reasonably accurate weight determination — by calculation, nameplate data, or engineering reference — before selecting gear.",type:"procedure"},
  { id:152,cat:"B",q:"A wire rope clip installation for an eye splice typically requires a minimum of:",opts:["1 clip","3 clips, correctly spaced and torqued","5 clips regardless of rope diameter","No clips if the eye is spliced"],ans:1,exp:"Standard practice for U-bolt wire rope clips on an eye termination is a minimum of 3 clips, spaced per the rope diameter and properly torqued.",type:"recall"},
  { id:153,cat:"B",q:"When lifting a load with two legs of a sling at an included angle, the load per leg is lowest when the angle between the legs is:",opts:["As small as possible (legs nearly vertical/parallel)","As large as possible (legs nearly horizontal)","Exactly 90°","Angle has no effect on load per leg"],ans:0,exp:"Keeping legs close to vertical (small included angle) minimizes tension per leg; spreading legs toward horizontal sharply increases leg tension.",type:"critical"},
  { id:154,cat:"C",q:"A worm gear set with a 40-tooth worm wheel and a single-start worm has a reduction ratio of:",opts:["1:1","20:1","40:1","80:1"],ans:2,exp:"Worm gear ratio = teeth on worm wheel ÷ number of starts on the worm = 40 ÷ 1 = 40:1.",type:"critical"},
  { id:155,cat:"C",q:"Diametral pitch (DP) of a gear is calculated as:",opts:["Pitch diameter ÷ number of teeth","Number of teeth ÷ pitch diameter","Number of teeth × pitch diameter","Outside diameter ÷ number of teeth"],ans:1,exp:"DP = N ÷ PD (teeth divided by pitch diameter). A higher DP means smaller, finer teeth.",type:"critical"},
  { id:156,cat:"C",q:"Backlash in a gear mesh is best described as:",opts:["The bearing preload on the gear shaft","The clearance between mating tooth surfaces when not under load","The total axial float of the gear","The angle of the pressure line"],ans:1,exp:"Backlash is the small gap between meshing teeth, needed to prevent binding from thermal expansion and manufacturing tolerance.",type:"recall"},
  { id:157,cat:"C",q:"Herringbone gears (two opposite-hand helical gears combined) are used primarily to:",opts:["Increase noise for safety alerts","Cancel out the axial thrust a single helical gear would produce","Allow non-parallel shafts","Reduce tooth strength"],ans:1,exp:"A single helical gear generates axial thrust; herringbone gears combine opposite helix angles side-by-side so the thrust components cancel.",type:"recall"},
  { id:158,cat:"C",q:"Which bearing type is specifically designed to self-align and compensate for shaft or housing misalignment?",opts:["Deep groove ball bearing","Cylindrical roller bearing","Spherical roller bearing","Angular contact bearing"],ans:2,exp:"The spherical outer raceway of a spherical roller bearing lets the inner assembly pivot slightly, tolerating shaft/housing misalignment.",type:"recall"},
  { id:159,cat:"C",q:"A bearing suffix of \"2RS\" indicates the bearing:",opts:["Has a tapered bore","Is sealed on both sides with rubber seals","Has double row rolling elements","Is shielded on both sides with metal shields"],ans:1,exp:"2RS = two rubber seals, one on each side, distinguishing it from ZZ (metal shields both sides).",type:"recall"},
  { id:160,cat:"C",q:"The recommended level for oil-bath lubrication of a rolling element bearing is:",opts:["The bearing fully submerged","Halfway up the lowest rolling element","Halfway up the highest rolling element","Level with the shaft centerline"],ans:1,exp:"Oil should reach about the center of the lowest ball/roller — fully submerging the bearing causes churning losses and overheating.",type:"procedure"},
  { id:161,cat:"C",q:"A \"floating\" bearing in a shaft assembly with a fixed (locating) bearing exists to:",opts:["Provide extra radial load capacity","Allow for thermal expansion of the shaft","Replace the need for lubrication","Increase bearing lifespan by 50%"],ans:1,exp:"As the shaft heats up and grows in length, a floating (non-locating) bearing's outer race can shift axially in its housing to absorb that growth.",type:"recall"},
  { id:162,cat:"C",q:"Babbitt bearing metal is primarily an alloy of:",opts:["Iron, carbon, and manganese","Tin (or lead), antimony, and copper","Aluminum, zinc, and magnesium","Nickel, chromium, and molybdenum"],ans:1,exp:"Babbitt is a soft tin- or lead-based alloy with antimony and copper, designed to embed contaminants and conform slightly under load.",type:"recall"},
  { id:163,cat:"C",q:"Standard taper-bore bearings (mounted on a tapered sleeve or shaft) typically use a taper ratio of:",opts:["1:4","1:12","1:50","1:100"],ans:1,exp:"1:12 is the standard taper ratio for taper-bore bearings and adapter sleeves in industrial applications.",type:"recall"},
  { id:164,cat:"C",q:"Which V-belt cross-section series is used for high-capacity, heavy-duty industrial drives?",opts:["A, B, C, D classical sections","2L, 3L, 4L, 5L fractional horsepower sections","3V, 5V, 8V narrow sections","O-ring round belt sections"],ans:2,exp:"The 3V/5V/8V narrow-profile belts are the high-capacity heavy-duty industrial series, carrying more power in a smaller cross-section.",type:"recall"},
  { id:165,cat:"C",q:"Correct V-belt tension is commonly checked by measuring deflection, which should be approximately:",opts:["1/64\" per inch of span","1/4\" per inch of span","1\" per inch of span","No deflection at all"],ans:0,exp:"A common rule of thumb targets about 1/64\" of deflection for every inch of belt span when a set force is applied at the belt's midpoint.",type:"procedure"},
  { id:166,cat:"C",q:"A banded (tied) V-belt set is specifically used to address:",opts:["Excessive belt cost","Belt turnover, whip, and vibration in multi-belt drives","Low horsepower requirements","Insufficient sheave groove depth"],ans:1,exp:"Tying multiple belts together with a backing band prevents individual belts from twisting (turnover) or whipping under vibration.",type:"recall"},
  { id:167,cat:"C",q:"Roller chain size #40 has a pitch of:",opts:["1/4 inch","3/8 inch","1/2 inch","5/8 inch"],ans:2,exp:"ANSI chain numbering: the leading digit(s) give pitch in eighths of an inch. #40 = 4/8\" = 1/2\" pitch.",type:"critical"},
  { id:168,cat:"C",q:"Minimum recommended wrap (arc of contact) of chain on the smaller sprocket in a typical drive is:",opts:["45° (1/8 wrap)","120° (1/3 wrap)","270° (3/4 wrap)","Full 360° wrap"],ans:1,exp:"At least 120 degrees (1/3) of wrap on the small sprocket is generally recommended to ensure adequate tooth engagement.",type:"recall"},
  { id:169,cat:"C",q:"Roller chain should typically be replaced once wear elongation reaches approximately:",opts:["0.5%","2%","10%","25%"],ans:1,exp:"About 2% elongation is the commonly used wear limit before a roller chain should be replaced, to avoid sprocket tooth damage and jumping.",type:"recall"},
  { id:170,cat:"C",q:"A jaw-type (Lovejoy-style) flexible coupling uses an elastomeric element known as a:",opts:["Bellows","Diaphragm","Spider","Grid"],ans:2,exp:"Jaw couplings use a rubber/urethane spider inserted between the two interlocking jaw hubs to cushion torque and absorb minor misalignment.",type:"recall"},
  { id:171,cat:"C",q:"Gear couplings are commonly chosen for high-horsepower applications because they:",opts:["Require no lubrication ever","Can transmit very high torque in a compact package while tolerating some misalignment","Never need replacement","Eliminate all shaft misalignment"],ans:1,exp:"Gear couplings pack high torque capacity into a small envelope and accommodate limited angular/parallel misalignment via crowned teeth.",type:"recall"},
  { id:172,cat:"C",q:"An overrunning (sprag or roller-ramp) clutch is used to:",opts:["Allow rotation in only one direction, freewheeling in reverse","Provide adjustable slip under all conditions","Lock two shafts together permanently","Increase output torque beyond input torque"],ans:0,exp:"An overrunning clutch drives in one direction and freewheels (overruns) if the output tries to spin faster or reverse — common as a backstop.",type:"recall"},
  { id:173,cat:"C",q:"A fluid coupling's driven member (connected to the load) is called the:",opts:["Impeller","Turbine","Stator","Torque converter"],ans:1,exp:"In a fluid coupling, the impeller is the driving member and the turbine is the driven member, connected only by circulating fluid.",type:"recall"},
  { id:174,cat:"C",q:"An angular contact bearing, used singly, is designed to carry:",opts:["Radial load only, no thrust","Radial load plus thrust in one direction","Thrust in both directions equally","No load — it is a seal only"],ans:1,exp:"A single-row angular contact bearing takes combined radial load with thrust in only one direction; paired/duplex sets handle both directions.",type:"recall"},
  { id:175,cat:"C",q:"When pressing a shaft out of a bearing, force must be applied through the:",opts:["Outer ring only","Rolling elements directly","Inner ring, not through the rolling elements","Cage/retainer"],ans:2,exp:"Force must be transmitted through the inner ring directly — pushing through the balls/rollers can brinell or damage the raceways.",type:"procedure"},
  { id:176,cat:"C",q:"The clearance between a plain (journal) bearing bore and the shaft is called:",opts:["Backlash","Diametral clearance","End float","Preload"],ans:1,exp:"Diametral clearance is the difference between the bearing bore diameter and the shaft (journal) diameter.",type:"recall"},
  { id:177,cat:"C",q:"Tilting pad bearings are primarily used to:",opts:["Eliminate the need for lubrication","Stabilize a shaft and dampen oil whirl at high speed","Increase axial load capacity only","Replace rolling element bearings in all applications"],ans:1,exp:"Tilting pads pivot to maintain a stable oil wedge under varying conditions, specifically countering oil-whirl instability at high speed.",type:"recall"},
  { id:178,cat:"C",q:"A tapered roller bearing's two main components are commonly called the:",opts:["Cup and cone","Race and cage","Shell and liner","Hub and spindle"],ans:0,exp:"The cup is the outer race; the cone is the inner race assembly with rollers and cage — classic tapered roller bearing terminology.",type:"recall"},
  { id:179,cat:"C",q:"Split (segmented) plain bearings are commonly rated with a lower resistance to:",opts:["Shock loading","Fluid contamination (soft babbitt embeds hard particles and scores the journal)","Axial expansion","Vibration"],ans:1,exp:"The soft babbitt surface of a plain bearing is more easily scored by hard contaminating particles than the hardened races of anti-friction bearings.",type:"critical"},
  { id:180,cat:"C",q:"A pillow block housing with grease lubrication should typically be filled to about:",opts:["10% of free space","1/3 (30%) of free space","Completely full","90% of free space"],ans:1,exp:"Overfilling a grease-lubricated housing causes churning and overheating; about 1/3 full is the common guideline.",type:"procedure"},
  { id:181,cat:"C",q:"The most common and strongest gear tooth pressure angle used today is:",opts:["14.5°","20°","28°","45°"],ans:1,exp:"20° is the modern standard pressure angle, providing a stronger tooth root than the older 14.5° standard.",type:"recall"},
  { id:182,cat:"C",q:"A rack and pinion gear set is specifically used to convert:",opts:["High torque into high speed","Rotary motion into linear motion","AC power into DC power","Linear vibration into rotary motion"],ans:1,exp:"The pinion's rotary motion drives the rack linearly (or vice versa) — a rack-and-pinion's defining function.",type:"recall"},
  { id:183,cat:"C",q:"Checking gear mesh contact pattern with Prussian blue (bluing) reveals:",opts:["The amount of backlash only","Where and how the tooth surfaces are actually making contact","The gear material hardness","The lubricant viscosity"],ans:1,exp:"Blue transferred onto the mating tooth shows the actual contact pattern, helping diagnose misalignment or improper mesh.",type:"procedure"},
  { id:184,cat:"C",q:"A multi-stage gear reducer has individual stage ratios of 4:1, 3:1, and 5:1. The overall reduction ratio is:",opts:["12:1","20:1","60:1","15:1"],ans:2,exp:"Multi-stage ratios multiply together: 4 × 3 × 5 = 60:1.",type:"critical"},
  { id:185,cat:"C",q:"If a pinion with 15 teeth drives a gear with 60 teeth, and the pinion turns at 1800 RPM, the gear's output speed is:",opts:["7200 RPM","450 RPM","1800 RPM","120 RPM"],ans:1,exp:"Ratio = 60/15 = 4:1 reduction. Output = 1800 ÷ 4 = 450 RPM.",type:"critical"},
  { id:186,cat:"C",q:"A key advantage of a synchronous (timing) belt over a standard V-belt is:",opts:["It never needs tension adjustment","It provides positive, slip-free power transmission via molded teeth","It runs cooler regardless of load","It requires no sprocket/pulley matching"],ans:1,exp:"Molded teeth meshing with a toothed pulley eliminate the slip inherent to friction-drive V-belts, giving precise, positive power transfer.",type:"recall"},
  { id:187,cat:"C",q:"Excessive tail-stock pressure when supporting a long shaft between centers during alignment work can cause:",opts:["No measurable effect","The shaft to deflect, introducing false runout readings","Increased shaft hardness","The shaft to shrink permanently"],ans:1,exp:"Too much center pressure can bow a long shaft slightly, causing runout/alignment readings that don't reflect the shaft's true condition.",type:"critical"},
  { id:188,cat:"C",q:"A coupling's rim speed threshold above which dynamic balancing is commonly recommended is approximately:",opts:["500 ft/min","1,500 ft/min","5,000 ft/min","20,000 ft/min"],ans:2,exp:"Roughly 5,000 ft/min rim speed is a commonly cited threshold above which coupling unbalance becomes significant enough to require dynamic balancing.",type:"recall"},
  { id:189,cat:"C",q:"Belt \"creep\" (the small difference between drive and driven pulley surface speed) occurs because:",opts:["The belt material stretches elastically under tension differences between tight and slack sides","The pulleys are always machined to different diameters","Belts always run at exactly the same speed as the pulley","Only synchronous belts experience creep"],ans:0,exp:"Elastic elongation differs between the tight and slack sides of a V-belt, causing a small amount of speed loss called creep — distinct from gross slip.",type:"critical"},
  { id:190,cat:"C",q:"When installing a bearing that requires heating for a shrink fit, standard practice limits induction/oven heating to about:",opts:["100°F (38°C)","250°F (121°C)","500°F (260°C)","800°F (427°C)"],ans:1,exp:"250°F is the commonly used maximum heating temperature for mounting antifriction bearings, avoiding tempering the bearing steel.",type:"recall"},
  { id:191,cat:"C",q:"A magnetic particle clutch's output torque is controlled by:",opts:["Varying the applied coil current","Varying the shaft diameter","Varying the number of particles physically added","Varying the ambient temperature only"],ans:0,exp:"Coil current sets the magnetic field strength gripping the ferrous particles, which directly determines the torque the clutch transmits.",type:"recall"},
  { id:192,cat:"C",q:"A centrifugal clutch engages automatically because:",opts:["It requires an external electrical signal","Rotational speed generates centrifugal force that forces friction shoes outward against the drum","It is manually actuated with a lever","It relies on hydraulic pressure from a separate pump"],ans:1,exp:"As RPM rises, centrifugal force throws weighted friction shoes outward into contact with the housing, engaging the drive with no external control needed.",type:"recall"},
  { id:193,cat:"C",q:"Hunting gear teeth ratios (using a prime number of teeth on one gear) in a gearset are chosen to:",opts:["Increase noise deliberately","Ensure each tooth meshes with every other tooth over time, distributing wear evenly","Reduce the gear's overall diameter","Eliminate the need for lubrication"],ans:1,exp:"A hunting tooth ratio avoids the same teeth always meshing together, spreading wear evenly across all teeth over many revolutions.",type:"recall"},
  { id:194,cat:"C",q:"What is the primary reason a keyway is cut into both a shaft and its mating hub?",opts:["To reduce shaft weight","To transmit torque between the shaft and hub without relying on friction alone","To allow the hub to slide freely","To balance the assembly"],ans:1,exp:"A key transmits torque positively between shaft and hub, rather than relying solely on the friction of an interference fit.",type:"recall"},
  { id:195,cat:"C",q:"A split (two-piece) coupling guard is generally preferred over a solid one-piece guard because it:",opts:["Is cheaper to manufacture only","Can be installed/removed without disturbing the coupling or shaft alignment","Provides less protection","Is required only for low-speed couplings"],ans:1,exp:"A split guard can be taken on and off around an already-aligned coupling without needing to move the shafts or break the coupling apart.",type:"recall"},
  { id:196,cat:"C",q:"What term describes the axial movement designed into some couplings/bearings to accommodate thermal shaft growth?",opts:["Backlash","End float","Preload","Runout"],ans:1,exp:"End float (axial float) is the intentional axial clearance allowing a shaft to grow thermally without binding.",type:"recall"},
  { id:197,cat:"C",q:"On a bandsaw or blade-type cutting tool, the correct blade tooth pitch for cutting thin-walled tubing requires:",opts:["The coarsest pitch available","At least 3 teeth in contact with the material thickness at all times","A single tooth spanning the full wall thickness","Pitch has no relationship to material thickness"],ans:1,exp:"A minimum of 3 teeth in contact prevents teeth from straddling the thin material and snagging/breaking off.",type:"recall"},
  { id:198,cat:"C",q:"Cylindrical roller bearings are well suited to carrying:",opts:["Heavy thrust loads only, no radial load","High radial loads with limited or no thrust capacity","Only very light loads at low speed","Combined radial and heavy bidirectional thrust equally"],ans:1,exp:"Cylindrical roller bearings excel at high radial load capacity but generally have limited to no thrust-load capability, depending on design.",type:"recall"},
  { id:199,cat:"C",q:"A needle roller bearing's key characteristic compared to other rolling bearings is:",opts:["It always includes a full inner race and cage","Small-diameter rollers giving high radial capacity in a compact radial envelope, sometimes without a separate inner race","It cannot handle any radial load","It is exclusively used for thrust applications"],ans:1,exp:"Needle bearings use thin, long rollers to pack high radial load capacity into minimal radial space, sometimes running directly on a hardened shaft.",type:"recall"},
  { id:200,cat:"E",q:"What gas is used to pre-charge a hydraulic accumulator?",opts:["Compressed air","Oxygen","Nitrogen","Hydrogen"],ans:2,exp:"Nitrogen is inert and safe under pressure; oxygen or compressed air risk combustion if mixed with atomized hydraulic oil.",type:"recall"},
  { id:201,cat:"E",q:"An accumulator's pre-charge pressure should generally never be set below approximately:",opts:["5% of maximum system pressure","25% of maximum system pressure","75% of maximum system pressure","100% of maximum system pressure"],ans:1,exp:"A common rule keeps pre-charge at a minimum of about 25% of max system pressure to protect the bladder/piston and ensure proper function.",type:"recall"},
  { id:202,cat:"E",q:"A weight-loaded accumulator's key advantage over a gas-charged accumulator is:",opts:["It is far more compact","It delivers constant pressure regardless of stored fluid volume","It requires no maintenance ever","It can be mounted in any orientation with no effect"],ans:1,exp:"A weight-loaded accumulator's pressure (force ÷ area) stays constant no matter how much fluid is stored, unlike gas-charged types where pressure varies with volume.",type:"recall"},
  { id:203,cat:"E",q:"The JIC standard flare angle for hydraulic tube fittings in North America is:",opts:["30°","37°","45°","60°"],ans:1,exp:"37° is the JIC (Joint Industry Conference) standard flare angle for North American hydraulic tube fittings.",type:"recall"},
  { id:204,cat:"E",q:"The primary cause of oxidation in hydraulic fluid is:",opts:["Excess heat","Low system pressure","Slow flow rate","Cold ambient temperature"],ans:0,exp:"Elevated operating temperature is the main driver of oil oxidation, which forms sludge, acids, and varnish deposits.",type:"recall"},
  { id:205,cat:"E",q:"A hydraulic reservoir's baffle plate primarily functions to:",opts:["Increase fluid velocity toward the pump inlet","Separate return flow from suction flow, giving fluid time to settle and de-aerate","Filter particulate contamination directly","Heat the fluid for cold starts"],ans:1,exp:"The baffle slows and redirects returning fluid, allowing air to escape and heat/contaminants to settle before the fluid reaches the pump suction.",type:"recall"},
  { id:206,cat:"E",q:"A Beta ratio (β) of 75 at 10 microns for a hydraulic filter means:",opts:["The filter removes 75% of all particles regardless of size","For every 75 particles ≥10 microns upstream, only 1 passes downstream (about 98.7% efficiency)","The filter has a 75-micron mesh size","The filter must be changed every 75 hours"],ans:1,exp:"Beta ratio = upstream particle count ÷ downstream particle count at a given size. β75 = (75-1)/75 ≈ 98.7% removal efficiency at 10 microns.",type:"critical"},
  { id:207,cat:"E",q:"A clogged pump inlet strainer is a classic cause of:",opts:["Increased system pressure","Cavitation, due to restricted suction flow dropping pressure below the fluid's vapor pressure","Higher fluid viscosity","Improved pump efficiency"],ans:1,exp:"Restricting suction flow drops the inlet pressure; if it falls below the fluid's vapor pressure, vapor bubbles form and collapse violently — cavitation.",type:"critical"},
  { id:208,cat:"E",q:"A dynamic (rod) seal is often designed to allow a very small amount of leakage in order to:",opts:["Reduce manufacturing cost","Lubricate and cool the seal/rod interface, extending seal life","Indicate the seal needs replacement","Reduce system pressure intentionally"],ans:1,exp:"A thin lubricating film from slight controlled leakage prevents dry-running friction and heat at the seal-to-rod interface.",type:"recall"},
  { id:209,cat:"E",q:"The purpose of a backup (anti-extrusion) ring installed with an O-ring is to:",opts:["Provide a completely independent secondary seal","Support the O-ring against extrusion into the clearance gap under pressure","Reduce the O-ring's compression","Replace the need for proper groove dimensions"],ans:1,exp:"Under high pressure, an O-ring can extrude into the clearance gap between mating parts; a backup ring blocks that gap and supports the O-ring.",type:"recall"},
  { id:210,cat:"E",q:"A labyrinth seal controls leakage along a rotating shaft by:",opts:["Direct rubbing contact with the shaft","Creating a tortuous, restrictive path with a series of close-clearance ridges","Chemically bonding to the shaft surface","Using a spring-loaded lip against the shaft"],ans:1,exp:"A labyrinth seal is non-contact, relying on a serpentine path of small clearances to restrict (not eliminate) leakage flow.",type:"recall"},
  { id:211,cat:"E",q:"A mechanical seal's primary and secondary sealing faces are lapped to be:",opts:["Rough and porous, for oil retention","Extremely flat and smooth","Deliberately convex to increase contact pressure","Left with visible machining marks"],ans:1,exp:"Mechanical seal faces are lapped extremely flat (within light bands) and smooth to create a reliable, low-leakage running interface.",type:"recall"},
  { id:212,cat:"E",q:"A balanced mechanical seal (versus unbalanced) is chosen specifically for:",opts:["Low-pressure, low-speed applications only","Higher pressure service, since it reduces the net closing force on the seal faces","Applications with no fluid present","Situations requiring no spring loading at all"],ans:1,exp:"Balancing the seal geometry reduces hydraulic closing force on the faces, allowing reliable operation at higher system pressures.",type:"recall"},
  { id:213,cat:"E",q:"Staggering the cut joints of successive packing rings in a stuffing box by 90°–180° is done to:",opts:["Make removal easier","Eliminate a straight-through leakage path along the shaft","Increase friction on the shaft","Reduce the number of rings needed"],ans:1,exp:"Offsetting each ring's cut prevents fluid from finding a direct path straight through aligned gaps in the packing set.",type:"procedure"},
  { id:214,cat:"E",q:"The purpose of a lantern ring in a pump's stuffing box is to:",opts:["Provide structural support to the shaft","Allow flushing fluid in for cooling and lubrication of the packing","Indicate when packing needs replacement visually","Increase shaft speed"],ans:1,exp:"A lantern ring has ports that admit flush fluid into the middle of the packing stack, cooling and lubricating it.",type:"recall"},
  { id:215,cat:"E",q:"Grease consistency (softness) is classified by the NLGI system based on:",opts:["Viscosity index","A cone penetration test result","Flash point","Dropping point"],ans:1,exp:"NLGI grades (000 through 6) are assigned from the standardized cone penetration test — lower numbers mean softer grease.",type:"recall"},
  { id:216,cat:"E",q:"Extreme Pressure (EP) additives in gear oils and greases primarily function to:",opts:["Lower the oil's viscosity for easier pumping","Prevent metal-to-metal micro-welding at asperity contact points under heavy load","Increase the oil's cloud point","Add color for identification"],ans:1,exp:"EP additives chemically react under high contact pressure to form a sacrificial film, preventing welding/scoring of highly loaded surfaces.",type:"recall"},
  { id:217,cat:"E",q:"An oil's Viscosity Index (VI) describes:",opts:["Its resistance to flow at one fixed temperature","How much its viscosity changes across a temperature range — higher VI means more stable viscosity","Its flash point in degrees Celsius","The additive package concentration"],ans:1,exp:"A high-VI oil maintains more consistent viscosity as temperature swings, which is desirable for equipment seeing wide temperature ranges.",type:"recall"},
  { id:218,cat:"E",q:"Boundary lubrication occurs when:",opts:["A full hydrodynamic film completely separates the surfaces","Surfaces are separated by only a very thin film, with asperities nearly in contact, relying on additive chemistry","Oil is pumped in externally at high pressure","No lubricant is present at all"],ans:1,exp:"In boundary lubrication the oil film is too thin for full separation, so anti-wear/EP additives carry much of the protective load.",type:"recall"},
  { id:219,cat:"E",q:"Hydrodynamic lubrication in a plain journal bearing is created by:",opts:["An external pump forcing oil in under pressure","The rotating shaft itself dragging oil into a converging wedge","Grease packed manually into the bearing","Capillary action alone, with no shaft rotation needed"],ans:1,exp:"Shaft rotation drags oil into the converging clearance space, building a self-generated pressure wedge that lifts and supports the shaft.",type:"recall"},
  { id:220,cat:"E",q:"Demulsibility of a lubricating oil refers to its ability to:",opts:["Resist oxidation at high temperatures","Separate cleanly from water rather than emulsifying with it","Maintain constant viscosity with temperature","Resist foaming under agitation"],ans:1,exp:"Good demulsibility lets water settle out and be drained, rather than forming a stable, damaging oil-water emulsion.",type:"recall"},
  { id:221,cat:"E",q:"What is the recommended maximum heating temperature for a sealed, pre-greased-for-life bearing before mounting?",opts:["About 125°F","About 175°F","About 300°F","About 450°F"],ans:1,exp:"Sealed bearings with factory grease and lip seals shouldn't be heated above roughly 175°F, to avoid damaging the seal material and grease.",type:"recall"},
  { id:222,cat:"E",q:"A large, slow-turning, heavily loaded shaft may need hydrostatic (rather than hydrodynamic) lubrication because:",opts:["Hydrostatic lubrication is always cheaper","At very low speed, self-generated hydrodynamic film may not form adequately to support the load","Hydrodynamic lubrication only works with grease","Slow shafts never need any lubrication"],ans:1,exp:"Below a certain speed, the shaft can't drag in enough oil to form a supporting wedge, so oil is pumped in externally under pressure instead.",type:"critical"},
  { id:223,cat:"E",q:"The ISO 4406 cleanliness code for hydraulic fluid reports particle counts greater than which micron sizes?",opts:["2, 8, and 16 microns","4, 6, and 14 microns","10, 20, and 30 microns","1, 5, and 25 microns"],ans:1,exp:"The current ISO 4406 code reports counts of particles larger than 4, 6, and 14 microns (e.g. 18/16/13).",type:"recall"},
  { id:224,cat:"E",q:"A common rule of thumb for sizing a hydraulic reservoir in an open-loop system is:",opts:["Equal to the pump's rated GPM","1-2 times the pump's rated GPM","3-4 times the pump's rated GPM","10 times the pump's rated GPM"],ans:2,exp:"Sizing the reservoir at roughly 3-4 times the pump's GPM rating gives adequate dwell time for cooling, de-aeration, and settling.",type:"recall"},
  { id:225,cat:"E",q:"When an accumulator's nitrogen pre-charge exceeds the system's actual maximum operating pressure, the result is:",opts:["The accumulator works normally with slightly reduced capacity","No hydraulic fluid can ever be stored, since system pressure can never compress the pre-charge","The accumulator discharges instantly on startup","The relief valve opens continuously"],ans:1,exp:"If pre-charge pressure is higher than the system can ever reach, the system can never overcome the gas charge to push fluid in at all.",type:"critical"},
  { id:226,cat:"E",q:"On a return-line hydraulic filter with an angled diffuser, the angled cut should face:",opts:["Directly toward the pump inlet","Away from the pump inlet","It makes no difference","Toward the top of the reservoir only"],ans:1,exp:"Directing the return flow away from the suction line reduces turbulence and aeration right at the pump inlet.",type:"procedure"},
  { id:309,cat:"E",q:"Straight-thread O-ring boss (ORB) fittings are preferred over tapered pipe thread fittings in hydraulic systems partly because they:",opts:["Are always cheaper to manufacture","Don't generate metal shavings or sealant residue during assembly, reducing system contamination","Require no O-ring at all","Can only be used at low pressure"],ans:1,exp:"Straight-thread ORB fittings seal via an O-ring rather than thread deformation/sealant, avoiding the contamination risk of tapered-thread assembly.",type:"recall"},
  { id:310,cat:"E",q:"A portable particle counter is valued in hydraulic maintenance because it:",opts:["Replaces the need for any filtration","Gives an immediate, objective fluid cleanliness reading on site","Only works in a certified laboratory","Measures viscosity, not particle count"],ans:1,exp:"Unlike sending a sample to a lab, a portable particle counter gives a real-time cleanliness code reading right at the machine.",type:"recall"},
  { id:311,cat:"E",q:"A hydraulic system's target ISO cleanliness code is 18/16/13, but a lab report comes back at 20/18/15. This means the fluid is:",opts:["Cleaner than target and needs no action","Dirtier than target and needs filtration or replacement","Exactly at target","Impossible to compare to the target"],ans:1,exp:"Higher ISO code numbers mean more particles present — 20/18/15 is dirtier than the 18/16/13 target and needs remediation.",type:"critical"},
  { id:227,cat:"D",q:"The maximum theoretical suction lift achievable by any pump at sea level is limited by atmospheric pressure to approximately:",opts:["10 feet","20 feet","34 feet","50 feet"],ans:2,exp:"Standard atmospheric pressure (14.7 psi) can theoretically support a column of water about 34 feet high — the absolute ceiling for suction lift.",type:"critical"},
  { id:228,cat:"D",q:"Hydraulic balancing of a multi-stage centrifugal pump's rotor is commonly achieved by:",opts:["Grinding down alternating impellers","Arranging impellers back-to-back so their axial thrusts oppose and cancel","Adding more bearings only","Increasing impeller diameter"],ans:1,exp:"Opposing impeller arrangement is a standard way to balance out the cumulative axial thrust that would otherwise build up in a multistage pump.",type:"recall"},
  { id:229,cat:"D",q:"Open or semi-open centrifugal pump impellers are generally preferred over closed impellers for pumping:",opts:["Clean, clear water only","Fibrous or stringy slurries that would clog a closed impeller","High-pressure boiler feedwater","Cryogenic liquids exclusively"],ans:1,exp:"Open/semi-open impellers have fewer enclosed passages to trap and clog on fibrous or stringy material.",type:"recall"},
  { id:230,cat:"D",q:"Wear rings in a centrifugal pump primarily function to:",opts:["Increase impeller diameter","Maintain close clearance limiting internal recirculation from discharge back to suction","Balance the rotating assembly","Provide the main bearing support"],ans:1,exp:"Close-clearance wear rings reduce internal leakage (recirculation) from the high-pressure discharge side back to the low-pressure suction side.",type:"recall"},
  { id:231,cat:"D",q:"A pump exhibiting high axial vibration at startup, most likely due to a double-suction impeller issue, points toward:",opts:["Coupling misalignment as the leading suspect","Simple electrical overload","Normal, expected behavior needing no investigation","Excessive suction pressure"],ans:0,exp:"Misalignment classically produces a dominant axial vibration signature, distinct from the primarily radial signature of pure unbalance.",type:"critical"},
  { id:232,cat:"D",q:"A positive displacement pump differs fundamentally from a centrifugal (dynamic) pump because it:",opts:["Uses an impeller to add kinetic energy to the fluid","Delivers a fixed volume of fluid per cycle/revolution regardless of discharge pressure","Cannot be used for high-viscosity fluids","Always requires a downstream relief valve to run safely at all"],ans:1,exp:"Positive displacement pumps trap and push a fixed fluid volume per cycle, so flow is nearly independent of discharge pressure (within pump limits) — but this is exactly why they need pressure relief protection if deadheaded.",type:"recall"},
  { id:233,cat:"D",q:"An internal gear pump's crescent-shaped divider serves to:",opts:["Increase pump speed","Isolate the inlet (suction) port from the outlet (discharge) port","Cool the pumped fluid","Balance the rotor axially"],ans:1,exp:"The crescent seal separates the expanding suction pocket from the contracting discharge pocket as the inner and outer gears rotate.",type:"recall"},
  { id:234,cat:"D",q:"A gate valve fully open provides:",opts:["Precise throttling control","A straight, nearly unrestricted flow path with minimal pressure drop","The tightest shutoff of any valve type","Automatic one-way flow control"],ans:1,exp:"A fully open gate valve gets its wedge/gate entirely out of the flow path, giving very low flow resistance — but poor throttling control.",type:"recall"},
  { id:235,cat:"D",q:"A needle valve is chosen over a gate or globe valve specifically for applications requiring:",opts:["Maximum flow with minimal restriction","Very fine, precise throttling control of flow","Automatic backflow prevention","Quarter-turn quick shutoff"],ans:1,exp:"A needle valve's tapered plug and fine-threaded stem give the most precise, gradual flow control of common valve types.",type:"recall"},
  { id:236,cat:"D",q:"A check valve's sole function is to:",opts:["Throttle flow precisely","Allow flow in one direction only, preventing backflow","Relieve excess system pressure","Measure flow rate"],ans:1,exp:"A check valve opens with forward flow and closes against reverse flow, preventing backflow — nothing more.",type:"recall"},
  { id:237,cat:"D",q:"Schedule 80 pipe compared to Schedule 40 pipe of the same nominal size has:",opts:["A larger outside diameter","The same outside diameter but a thicker wall (smaller inside diameter)","A smaller outside diameter","No difference at all"],ans:1,exp:"Pipe schedules share a constant OD for a given nominal size; higher schedule numbers mean a thicker wall, reducing the inside diameter.",type:"critical"},
  { id:238,cat:"D",q:"If the inside diameter of a pipe is doubled while flow rate stays constant, fluid velocity will:",opts:["Double","Stay the same","Be reduced to one quarter","Be reduced to one half"],ans:2,exp:"Cross-sectional area scales with diameter squared, so velocity (which is inversely proportional to area at constant flow) drops to 1/4.",type:"critical"},
  { id:239,cat:"D",q:"American standard tapered pipe threads are designated by the letters:",opts:["NPS","NPT","UNC","BSP"],ans:1,exp:"NPT = National Pipe Taper, the standard tapered thread form used on North American pipe fittings.",type:"recall"},
  { id:240,cat:"D",q:"Diaphragm valves are especially well suited for handling:",opts:["Cryogenic gases at very high pressure","Corrosive acids and caustic fluids, since the diaphragm isolates the fluid from metal parts","Superheated steam above 500°F","High-vacuum applications only"],ans:1,exp:"The flexible diaphragm keeps the corrosive process fluid away from the valve body and stem, making it a common choice for acid/caustic service.",type:"recall"},
  { id:241,cat:"D",q:"An off-line (kidney-loop) hydraulic filter is specifically valuable when:",opts:["The system pump runs continuously at full flow","A pressure-compensated pump frequently sits at standby with near-zero main flow","The reservoir is oversized","Only particulate above 100 microns needs removal"],ans:1,exp:"Because it has its own dedicated circulation, an off-line filter keeps cleaning the fluid even while the main pump idles at standby.",type:"recall"},
  { id:242,cat:"D",q:"How much pressure is created by a 100-foot column of water?",opts:["10 psi","20 psi","43.3 psi","100 psi"],ans:2,exp:"Pressure = 0.433 × height(ft) × specific gravity. For water: 0.433 × 100 × 1.0 = 43.3 psi.",type:"critical"},
  { id:243,cat:"F",q:"The most common cause of vibration in rotating machinery is:",opts:["Bent shafts","Unbalance","Bad bearings","Resonance"],ans:1,exp:"Unbalance (uneven mass distribution around the rotating centerline) is the single most common vibration source in rotating equipment.",type:"recall"},
  { id:244,cat:"F",q:"A vibration signature dominated by 1x running speed in the radial direction is most characteristic of:",opts:["Misalignment","Unbalance","Bearing defects","Electrical looseness in a motor's stator"],ans:1,exp:"Simple unbalance produces a clean 1x RPM peak, primarily radial — a classic diagnostic signature.",type:"critical"},
  { id:245,cat:"F",q:"A vibration signature with strong axial components at 1x, 2x, and 3x running speed most often indicates:",opts:["Unbalance","Misalignment","Cavitation","Electrical noise"],ans:1,exp:"Misalignment classically shows strong axial vibration content at multiples of running speed, unlike unbalance which is primarily radial at 1x.",type:"critical"},
  { id:246,cat:"F",q:"High-frequency vibration components well above running speed, especially non-integer multiples, typically point to:",opts:["Unbalance","Bearing defects","Simple misalignment","Soft foot"],ans:1,exp:"Bearing defect frequencies (related to raceway/rolling element geometry) are usually much higher and non-synchronous relative to shaft speed.",type:"recall"},
  { id:247,cat:"F",q:"Of the recognized types of rotor unbalance, which is generally the most difficult to diagnose and correct because it requires two-plane correction?",opts:["Static unbalance","Couple unbalance","Dynamic unbalance","Quasi-static unbalance"],ans:2,exp:"Dynamic unbalance combines both static and couple components, requiring correction in two separate planes — the most complex case.",type:"critical"},
  { id:248,cat:"F",q:"Couple unbalance is specifically characterized by:",opts:["A single heavy spot on one plane only","Two equal unbalance masses 180° apart, located in two separate planes","No detectable vibration at all","Excess axial thrust only"],ans:1,exp:"Two equal masses opposite each other but in different planes create a rocking couple with no net static force, but real vibration.",type:"recall"},
  { id:249,cat:"F",q:"A displacement (proximity/eddy-current) transducer is preferred for measuring shaft vibration without contact because:",opts:["It must be bolted directly to the rotating shaft","It senses shaft position electromagnetically without touching the shaft, unlike case-mounted accelerometers","It cannot be used on rotating equipment","It only works on non-metallic shafts"],ans:1,exp:"An eddy-current proximity probe measures the actual shaft's position/movement directly, without physical contact, unlike housing-mounted accelerometers.",type:"recall"},
  { id:250,cat:"F",q:"An accelerometer commonly uses which sensing element to generate a vibration signal?",opts:["A piezoelectric crystal","A magnet and coil","A strain-gauge foil only","A fiber-optic sensor"],ans:0,exp:"Piezoelectric accelerometers generate a voltage proportional to acceleration as the crystal is mechanically stressed by vibration.",type:"recall"},
  { id:251,cat:"F",q:"To avoid resonance damage, a rotating shaft's operating speed should generally be kept at least how far from its natural (critical) frequency?",opts:["5%","10%","20%","50%"],ans:2,exp:"A commonly used margin keeps continuous operating speed at least 20% away from any natural/critical frequency of the shaft system.",type:"recall"},
  { id:252,cat:"F",q:"Which non-destructive testing (NDT) method uses a high-frequency sound wave to detect internal discontinuities?",opts:["Eddy current testing","Magnetic particle inspection","Ultrasonic testing","Dye penetrant inspection"],ans:2,exp:"Ultrasonic testing (UT) sends high-frequency sound waves through a material and analyzes reflections to find internal flaws.",type:"recall"},
  { id:253,cat:"F",q:"Magnetic particle inspection is limited to:",opts:["Ferromagnetic materials only","Any material regardless of magnetic properties","Non-metals exclusively","Liquids only"],ans:0,exp:"Magnetic particle inspection relies on magnetizing the part and observing flux leakage, so it only works on ferromagnetic materials.",type:"recall"},
  { id:254,cat:"F",q:"Radiographic (X-ray/gamma) inspection has a key advantage over ultrasonic or magnetic particle testing in that it can:",opts:["Only inspect surface defects","Reveal internal flaws even when hidden behind other assembled components","Be performed without any radiation safety precautions","Only be used on non-metallic parts"],ans:1,exp:"Radiography can penetrate through assembled components to image internal defects that other methods, needing direct surface access, cannot reach.",type:"recall"},
  { id:255,cat:"F",q:"Liquid penetrant is drawn into fine surface-breaking defects by:",opts:["Gravity alone","Capillary action","Magnetic attraction","Air pressure differential"],ans:1,exp:"Capillary action draws the low-viscosity penetrant into narrow surface cracks and porosity.",type:"recall"},
  { id:256,cat:"F",q:"Before liquid penetrant testing, the surface must be free of contaminants (oil, grease, water) for at least what distance beyond the inspection area?",opts:["1/4 inch","1 inch","1 foot","No clearance is required"],ans:1,exp:"A standard surface-prep requirement calls for at least 1 inch of clean surface surrounding the area being inspected.",type:"recall"},
  { id:257,cat:"F",q:"A CMMS (Computerized Maintenance Management System) is primarily used to manage:",opts:["Only employee payroll","PM scheduling, work orders, parts inventory, and equipment history","Only purchase orders","Only safety training records"],ans:1,exp:"A CMMS centralizes preventive maintenance scheduling, work order tracking, spare parts inventory, and equipment maintenance history.",type:"recall"},
  { id:258,cat:"F",q:"An oil sample for lab analysis should ideally be taken:",opts:["From the drain plug after the system has sat idle overnight","From a dedicated sampling port with the system at normal operating temperature and the oil circulating","By dipping an open cup into the reservoir surface","Only when the oil already looks visibly dirty"],ans:1,exp:"Sampling at operating temperature with oil circulating (not from a drain, where settled contaminants concentrate) gives a representative result.",type:"procedure"},
  { id:259,cat:"F",q:"An ISO oil cleanliness code reported as 18/16/13 describes particle counts at which micron thresholds?",opts:[">2, >5, >15 microns",">4, >6, >14 microns",">10, >25, >50 microns",">1, >2, >4 microns"],ans:1,exp:"The current ISO 4406 code format reports particle counts greater than 4, 6, and 14 microns, in that order.",type:"recall"},
  { id:260,cat:"F",q:"The fundamental purpose of a governor on a prime mover is to:",opts:["Control fuel/steam quality","Control rotational speed","Control lubrication flow","Control exhaust temperature only"],ans:1,exp:"A governor's core job is regulating speed by adjusting fuel or steam admission in response to load changes.",type:"recall"},
  { id:261,cat:"F",q:"A properly functioning governing system executes its correction cycle in the order:",opts:["Correction, then detection, then transmission","Detection, then transmission, then correction","Transmission, then correction, then detection","All three happen simultaneously with no defined order"],ans:1,exp:"A governor must first detect a speed deviation, transmit that signal, then apply the correction — in that sequence.",type:"recall"},
  { id:262,cat:"F",q:"An isochronous governor is defined by its ability to:",opts:["Allow speed to drop as load increases","Maintain one constant speed regardless of load changes","Only function above a minimum load","Require manual adjustment at every load change"],ans:1,exp:"Isochronous governing holds speed constant across the entire load range, with zero steady-state droop.",type:"recall"},
  { id:263,cat:"F",q:"A prime mover repeatedly speeding up and slowing down due to an unstable governor is exhibiting a condition called:",opts:["Speed droop","Hunting","Speed drift","Overspeed"],ans:1,exp:"Cyclical speed oscillation from governor instability is called hunting.",type:"recall"},
  { id:264,cat:"F",q:"An overspeed trip is typically set to activate at approximately what percentage above normal maximum operating speed?",opts:["0-5%","10-15%","30-40%","75-100%"],ans:1,exp:"A commonly used overspeed trip setting is about 10-15% above normal maximum operating speed, giving margin above normal governing action.",type:"recall"},
  { id:265,cat:"F",q:"On startup of a gas turbine, the unit is typically motored/purged to what percentage of maximum operating speed before fuel ignition?",opts:["5-10%","20-30%","50-60%","80-90%"],ans:1,exp:"Roughly 20-30% of max speed is a typical purge/motoring target reached before fuel is introduced and ignited.",type:"recall"},
  { id:266,cat:"F",q:"The flow sequence through a gas turbine (Brayton cycle) is:",opts:["Turbine, combustion chamber, compressor","Combustion chamber, compressor, turbine","Compressor, combustion chamber, turbine","Compressor, turbine, combustion chamber"],ans:2,exp:"Air is compressed first, mixed with fuel and burned in the combustion chamber, then expanded through the turbine.",type:"recall"},
  { id:267,cat:"F",q:"Roughly what share of the power produced by a gas turbine is consumed just driving its own compressor?",opts:["10%","25%","65%","95%"],ans:2,exp:"A large fraction — often cited around 65% — of a gas turbine's generated power is used internally to drive its own compressor and accessories.",type:"recall"},
  { id:268,cat:"F",q:"On a steam turbine, blading in the low-pressure (LP) stages typically experiences the most erosion because of:",opts:["Extremely high steam temperature","Wet, moisture-laden steam impacting the blades","Excessive lubrication","Low rotational speed"],ans:1,exp:"LP stage steam is wetter (higher moisture content), and water droplet impact erodes the trailing edges of LP blading over time.",type:"recall"},
  { id:269,cat:"F",q:"Turbine blade shrouding, combined with a labyrinth-style seal, is used to:",opts:["Increase blade weight for balance","Control steam leakage past the blade tips","Reduce blade material cost","Eliminate the need for a governor"],ans:1,exp:"Shrouds tie blade tips together and, combined with labyrinth sealing, restrict steam bypass leakage at the tips.",type:"recall"},
  { id:270,cat:"F",q:"Jacking oil pumps on large turbine-generator sets serve to:",opts:["Cool the generator windings","Lift the shaft slightly off the bearings before rotation begins, preventing dry-start wiping damage","Replace the main lubrication system entirely","Control governor response speed"],ans:1,exp:"A thin oil film from the jacking pump lifts a very heavy shaft off the bearing surface before rotation, preventing metal-to-metal wiping at startup.",type:"recall"},
  { id:271,cat:"F",q:"Gas turbine bearing lubrication systems commonly rely on which seal type to keep oil out of the hot gas path?",opts:["O-ring seals only","Labyrinth seals combined with an air buffer","Standard lip seals rated for 200°F","Mechanical face seals exclusively"],ans:1,exp:"Labyrinth seals paired with a pressurized air buffer are a common approach to keeping lubricating oil away from the turbine's hot section.",type:"recall"},
  { id:272,cat:"F",q:"A hydraulic-type governor typically senses the need to correct speed by monitoring changes in:",opts:["Fuel viscosity","Pressure from a shaft-driven pilot pump","Ambient air temperature","Exhaust gas color"],ans:1,exp:"A shaft-driven pilot pump's output pressure rises and falls with speed, giving the hydraulic governor its speed-sensing signal.",type:"recall"},
  { id:273,cat:"F",q:"A basic overspeed mechanical trip pin is held in its normal running position by:",opts:["Spring tension exceeding the centrifugal force acting on the pin at normal speed","Centrifugal force always exceeding spring tension","Hydraulic pressure only, with no spring involved","Gravity alone with no spring at all"],ans:0,exp:"The spring holds the trip pin in place until an overspeed condition generates enough centrifugal force to overcome spring tension and release it.",type:"recall"},
  { id:274,cat:"A",q:"According to standard shop safety practice, the maximum allowable gap between a bench grinder's tool rest and the wheel is:",opts:["1/16\"","1/8\"","1/4\"","1/2\""],ans:1,exp:"A gap no greater than 1/8\" (3mm) prevents work from being pulled into the gap and jamming, which can shatter the wheel.",type:"recall"},
  { id:275,cat:"A",q:"Before starting work on any equipment, the most important condition to verify is that it is:",opts:["Roped off with warning tape","In a verified zero-energy (locked out) state","Scheduled for maintenance in the CMMS","Recently cleaned"],ans:1,exp:"Confirming true isolation of all energy sources (zero-energy state) is the core purpose of lockout/tagout before any work begins.",type:"critical"},
  { id:276,cat:"A",q:"The three elements of the fire triangle are:",opts:["Fuel, heat, oxygen","Fuel, spark, smoke","Heat, smoke, ash","Oxygen, pressure, temperature"],ans:0,exp:"Fire requires fuel, heat, and oxygen together — removing any one of the three extinguishes it.",type:"recall"},
  { id:277,cat:"A",q:"A Class D fire extinguisher is specifically rated for:",opts:["Ordinary combustibles like wood and paper","Flammable liquids","Energized electrical equipment","Combustible metals"],ans:3,exp:"Class D extinguishers use special dry powder agents for burning metals (magnesium, titanium, sodium, etc.) — water can cause explosive reactions.",type:"recall"},
  { id:278,cat:"A",q:"Using a solid stream of water on an energized electrical (Class C) fire creates a serious risk because:",opts:["Water evaporates too quickly to be effective","Water conducts electricity, creating a shock hazard back to the operator","Water always makes electrical fires burn hotter","Water reacts explosively with all wiring insulation"],ans:1,exp:"A solid water stream provides a conductive path back to the nozzle/operator if the equipment is still energized — a serious electrocution risk.",type:"critical"},
  { id:279,cat:"A",q:"According to standard occupational hearing protection guidance, hearing protection becomes required at noise levels exceeding approximately:",opts:["65 dBA","85 dBA","110 dBA","130 dBA"],ans:1,exp:"85 dBA (as an 8-hour time-weighted average) is a widely used regulatory threshold triggering mandatory hearing protection.",type:"recall"},
  { id:280,cat:"A",q:"A lifting device (crane, hoist) should be inspected by a competent person at minimum:",opts:["Only after an incident occurs","At least once a year","Every ten years","Never, unless it fails"],ans:1,exp:"Standard regulatory guidance requires a documented competent-person inspection of lifting devices at least annually.",type:"recall"},
  { id:281,cat:"A",q:"The most common root cause cited for industrial accidents is generally:",opts:["Equipment malfunction alone","Human carelessness / unsafe acts","Weather conditions","Insufficient signage"],ans:1,exp:"Studies and safety training consistently point to unsafe human behavior/carelessness as the leading root cause, more than equipment failure alone.",type:"recall"},
  { id:282,cat:"A",q:"The tap drill size formula for a Unified thread is approximately:",opts:["Major diameter + pitch","Major diameter − pitch","Major diameter × pitch","Major diameter ÷ pitch"],ans:1,exp:"Tap drill diameter ≈ major diameter − pitch (1/threads-per-inch). For 1/2-13 UNC: 0.500 − (1/13) ≈ 0.4231\", closest to 27/64\".",type:"critical"},
  { id:283,cat:"A",q:"On a bolt head, radial line markings indicate:",opts:["The thread series","The bolt's grade (tensile/proof strength)","The bolt's length","The manufacturer's country of origin"],ans:1,exp:"Grade markings (lines or numbers) on the bolt head denote its strength grade, which determines proper torque values.",type:"recall"},
  { id:284,cat:"A",q:"A castellated (slotted) nut is used with a cotter pin specifically to:",opts:["Increase clamping force","Provide positive mechanical locking against loosening, especially where vibration is present","Allow the nut to be removed without tools","Replace the need for a washer"],ans:1,exp:"The cotter pin passes through the bolt and nut slots, positively preventing the nut from backing off under vibration.",type:"recall"},
  { id:285,cat:"A",q:"A nylon-insert (nyloc) locknut is generally rated for:",opts:["Unlimited reuse with no loss of locking torque","One-time use, since the nylon collar deforms and loses reliable locking force after removal","Only low-vibration applications","High-temperature service above 500°F"],ans:1,exp:"The nylon insert deforms to grip the threads on first installation and typically shouldn't be relied upon for full locking torque after reuse.",type:"recall"},
  { id:286,cat:"A",q:"A Helicoil (wire thread insert) is used to:",opts:["Cut a new external thread","Repair a damaged or stripped internal (tapped) thread","Lock a stud permanently into a hole","Increase a bolt's tensile strength"],ans:1,exp:"A Helicoil restores a stripped or damaged internal thread by providing a new precision thread surface inside the original hole.",type:"recall"},
  { id:287,cat:"A",q:"The standard included angle for an inch-series countersunk flat head screw is:",opts:["60°","82°","90°","118°"],ans:1,exp:"82° is the standard included angle for inch-series flat/countersunk screw heads (metric uses 90°).",type:"recall"},
  { id:288,cat:"A",q:"Adding lubricant to a threaded fastener before torquing will:",opts:["Increase the torque needed for the same clamp load","Decrease the torque needed to achieve the same clamp load","Have no effect on the relationship between torque and clamp load","Eliminate the need to torque the fastener at all"],ans:1,exp:"Lubrication lowers friction, so less applied torque produces the same clamp load — torque specs must state whether they assume lubricated or dry threads.",type:"critical"},
  { id:289,cat:"A",q:"In GD&T, the symbol resembling a circled cross (⊕) represents:",opts:["Flatness","Position (true position) tolerance","Concentricity","Parallelism"],ans:1,exp:"The circled cross is the position tolerance symbol, one of the most frequently used GD&T callouts on drawings.",type:"recall"},
  { id:290,cat:"A",q:"Maximum Material Condition (MMC) in GD&T refers to the condition where a feature:",opts:["Contains the least material possible","Contains the most material possible (largest shaft OD, smallest hole ID)","Is at its nominal/basic dimension exactly","Has the loosest possible fit"],ans:1,exp:"MMC is the dimensional extreme where the most material is present — largest permissible shaft, or smallest permissible hole.",type:"recall"},
  { id:291,cat:"A",q:"In third-angle projection (the North American drawing standard), the right-side view is placed:",opts:["To the left of the front view","Above the front view","To the right of the front view","Below the top view"],ans:2,exp:"Third-angle projection places the right side view to the right of the front view — opposite of first-angle projection used in Europe.",type:"recall"},
  { id:292,cat:"A",q:"A hidden (dashed) line on a technical drawing represents:",opts:["A visible edge","An edge or surface not visible from the current view","A dimension boundary","A center of symmetry"],ans:1,exp:"Hidden lines show edges/surfaces that exist but are obscured from view in the current projection.",type:"recall"},
  { id:293,cat:"A",q:"Toughness, as a material property, is best described as the ability to:",opts:["Resist scratching or indentation","Withstand shock or impact loading without fracturing","Return to original shape after deformation","Conduct heat efficiently"],ans:1,exp:"Toughness is a material's capacity to absorb energy and resist fracture under sudden impact/shock loads.",type:"recall"},
  { id:294,cat:"A",q:"Martensite, the hard grain structure formed in steel, results from:",opts:["Slow furnace cooling (annealing)","Rapid quenching from above the upper critical temperature","Tempering at low temperature only","Cold rolling with no heat applied"],ans:1,exp:"Quenching quickly from above the upper critical (austenitizing) temperature traps carbon in a distorted lattice, forming hard martensite.",type:"recall"},
  { id:295,cat:"A",q:"Case hardening produces a hard outer shell over a tough core, typically to a depth of about:",opts:["0.005\"-0.090\"","0.5\"-2.0\"","3\"-5\"","There is no typical depth range"],ans:0,exp:"Case hardening (carburizing, nitriding, etc.) typically produces a hardened layer roughly 0.005\" to 0.090\" deep.",type:"recall"},
  { id:296,cat:"A",q:"Nitriding is a specific method of:",opts:["Through-hardening the entire cross-section","Case hardening by diffusing nitrogen into the surface","Stress relieving only","Softening steel for machining"],ans:1,exp:"Nitriding diffuses nitrogen into the surface at moderate temperature, producing a hard case without a full quench.",type:"recall"},
  { id:297,cat:"A",q:"Normalizing steel is done primarily to:",opts:["Maximize softness for machining","Refine and uniform the grain structure while relieving internal stresses","Produce maximum hardness","Add a hard outer case"],ans:1,exp:"Normalizing (heating above critical temperature, then air cooling) refines grain structure and relieves stress, unlike annealing (max softness) or case hardening.",type:"recall"},
  { id:298,cat:"A",q:"The Rockwell hardness test measures a material's:",opts:["Elastic modulus","Resistance to penetration under a fixed load","Resistance to abrasive wear only","Melting temperature"],ans:1,exp:"Rockwell hardness is derived directly from the depth of indentation left by a standardized indenter under a known load.",type:"recall"},
  { id:299,cat:"A",q:"An AISI/SAE 4-digit steel designation's first digit generally identifies:",opts:["The percentage of carbon","The type/series of steel (its major alloying system)","The exact tensile strength","The manufacturer"],ans:1,exp:"The first digit (or two) of the AISI/SAE code identifies the alloy series/type; the last two digits typically indicate carbon content.",type:"recall"},
  { id:300,cat:"A",q:"Brass is an alloy of copper and:",opts:["Tin","Zinc","Lead","Nickel"],ans:1,exp:"Brass is copper-zinc; bronze (a different alloy) is copper-tin.",type:"recall"},
  { id:301,cat:"A",q:"18-4-1 High-Speed Steel (HSS) retains its cutting edge at red heat mainly due to its high content of:",opts:["Manganese","Tungsten","Silicon","Nickel"],ans:1,exp:"HSS tool bits owe their red-hardness largely to about 18% tungsten content (plus chromium and vanadium).",type:"recall"},
  { id:302,cat:"A",q:"Phosphorus is generally considered an undesirable trace element in steel because it:",opts:["Increases toughness significantly","Promotes brittleness (cold-shortness)","Improves weldability","Increases corrosion resistance"],ans:1,exp:"Phosphorus segregation makes steel brittle at lower temperatures — a classic undesirable trace impurity.",type:"recall"},
  { id:303,cat:"A",q:"300-series stainless steels (chromium-nickel alloys) are generally:",opts:["Strongly magnetic","Non-magnetic (austenitic)","Identical in composition to 400-series steels","Only usable at cryogenic temperatures"],ans:1,exp:"300-series austenitic stainless steels (e.g. 304, 316) are chromium-nickel alloys that are non-magnetic in their normal annealed state.",type:"recall"},
  { id:304,cat:"A",q:"On a tempering color chart, as carbon steel is progressively heated, its surface oxide color changes:",opts:["From dark blue toward pale straw as it gets hotter","From pale straw toward dark blue as it gets hotter","Colors don't correlate with temperature at all","From black directly to white with no intermediate colors"],ans:1,exp:"Temper colors progress from pale/light straw at lower temperatures through to dark blue as the steel gets progressively hotter.",type:"recall"},
  { id:305,cat:"A",q:"A dial indicator used to measure gear backlash should contact the gear tooth at approximately:",opts:["The tooth root","The pitch line","The very tip of the tooth","Anywhere is equally valid"],ans:1,exp:"Backlash measurements are taken with the indicator contacting near the pitch line, for a consistent, meaningful reading.",type:"procedure"},
  { id:306,cat:"A",q:"A vernier caliper's primary advantage over a steel rule is:",opts:["It can measure much greater lengths","It provides finer resolution (typically to 0.001\") using a sliding vernier scale","It requires no reading skill at all","It can only measure external dimensions"],ans:1,exp:"The vernier (or digital) scale lets a caliper resolve measurements far more precisely than a rule's smallest graduation allows alone.",type:"recall"},
  { id:307,cat:"A",q:"A dial bore gauge is specifically designed to measure:",opts:["External diameters only","Internal bore diameter and out-of-round/taper conditions","Surface hardness","Thread pitch diameter"],ans:1,exp:"A bore gauge's spring-loaded contacts measure internal diameters precisely, revealing taper, out-of-round, or bell-mouth wear.",type:"recall"},
  { id:308,cat:"A",q:"A dead-blow hammer is preferred over a standard steel hammer when:",opts:["Striking hardened steel dies directly","Seating precision parts or bearings where rebound and marring must be minimized","Driving large spikes into concrete","Maximum single-blow force is required"],ans:1,exp:"The internal shot-filled head of a dead-blow hammer absorbs rebound energy, minimizing bounce-back and surface marring on precision parts.",type:"recall"},
];
